        metrics.AddAspNetCoreInstrumentation()
            .AddHttpClientInstrumentation()
            .AddRuntimeInstrumentation();
    })

    Note that on .NET 8+, `AddHttpClientInstrumentation()` can be replaced by manual meter subscriptions:

