InvokeMember and CreateInstance

Use System.Type.InvokeMember*?displayProperty=nameWithType to invoke a member of a type. The CreateInstance methods of various classes, such as System.Activator.CreateInstance*?displayProperty=nameWithType and System.Reflection.Assembly.CreateInstance*?displayProperty=nameWithType, are specialized forms of InvokeMember that create new instances of the specified type. The Binder class is used for overload resolution and argument coercion in these methods.

The following example shows the three possible combinations of argument coercion (type conversion) and member selection. In Case 1, no argument coercion or member selection is needed. In Case 2, only member selection is needed. In Case 3, only argument coercion is needed.

    public class CustomBinderDriver
    {
        public static void Main()
        {
            Type t = typeof(CustomBinderDriver);
            CustomBinder binder = new CustomBinder();
            BindingFlags flags = BindingFlags.InvokeMethod | BindingFlags.Instance |
                BindingFlags.Public | BindingFlags.Static;
            object[] args;

            // Case 1. Neither argument coercion nor member selection is needed.
            args = new object[] {};
            t.InvokeMember("PrintBob", flags, binder, null, args);

            // Case 2. Only member selection is needed.
            args = new object[] {42};
            t.InvokeMember("PrintValue", flags, binder, null, args);

            // Case 3. Only argument coercion is needed.
            args = new object[] {"5.5"};
            t.InvokeMember("PrintNumber", flags, binder, null, args);
        }

        public static void PrintBob()
        {
            Console.WriteLine("PrintBob");
        }

        public static void PrintValue(long value)
        {
            Console.WriteLine($"PrintValue({value})");
        }

        public static void PrintValue(string value)
        {
            Console.WriteLine("PrintValue\"{0}\")", value);
        }

        public static void PrintNumber(double value)
        {
            Console.WriteLine($"PrintNumber ({value})");
        }
    }

    Public Class CustomBinderDriver
        Public Shared Sub Main()
            Dim t As Type = GetType(CustomBinderDriver)
            Dim binder As New CustomBinder()
            Dim flags As BindingFlags = BindingFlags.InvokeMethod Or BindingFlags.Instance Or
                BindingFlags.Public Or BindingFlags.Static
            Dim args() As Object

            ' Case 1. Neither argument coercion nor member selection is needed.
            args = New object() {}
            t.InvokeMember("PrintBob", flags, binder, Nothing, args)

            ' Case 2. Only member selection is needed.
            args = New object() {42}
            t.InvokeMember("PrintValue", flags, binder, Nothing, args)

            ' Case 3. Only argument coercion is needed.
            args = New object() {"5.5"}
            t.InvokeMember("PrintNumber", flags, binder, Nothing, args)
        End Sub

        Public Shared Sub PrintBob()
            Console.WriteLine("PrintBob")
        End Sub

        Public Shared Sub PrintValue(value As Long)
            Console.WriteLine("PrintValue ({0})", value)
        End Sub

