            CultureInfo.CurrentCulture.NumberFormat)

            lvi.SubItems.Add("Not Started")
            lvi.SubItems.Add("1")
            lvi.SubItems.Add(guid.ToString())
            lvi.SubItems.Add("---")
            lvi.SubItems.Add("---")
            lvi.Tag = guid

            Me.listView1.Items.Add(lvi)

            Return lvi

        End Function

