            InitializeDelegates()

        End Sub
        ' </snippet21>

        ' <snippet20>
        Protected Overridable Sub InitializeDelegates()
            onProgressReportDelegate = _
                New SendOrPostCallback(AddressOf ReportProgress)
            onCompletedDelegate = _
                New SendOrPostCallback(AddressOf CalculateCompleted)
