        Public ReadOnly Property IsPrime() As Boolean
            Get
                ' Raise an exception if the operation failed
                ' or was canceled.
                RaiseExceptionIfNecessary()

                ' If the operation was successful, return
                ' the property value.
                Return isPrimeValue
            End Get
        End Property
    End Class
