            sw.Stop();
            Console.WriteLine($"{result} in {sw.Elapsed}");

            string aheadPattern = @"^((?=[A-Z])\w+\.)*[A-Z]\w*$";
            sw = Stopwatch.StartNew();
            result = Regex.IsMatch(input, aheadPattern, RegexOptions.IgnoreCase);
            sw.Stop();
            Console.WriteLine($"{result} in {sw.Elapsed}");
        }
    }
