    //          6E 74 65 6E 63 65 2E 20 54 68 69 73 20 69 73 20 74 68 65 20
    //          73 65 63 6F 6E 64 20 73 65 6E 74 65 6E 63 65 2E 20
    //
    //       Decoded: This is the first sentence. This is the second sentence.

