A decoder converts a byte array that reflects a particular character encoding into a set of characters, either in a character array or in a string. To decode a byte array into a character array, you call the System.Text.Encoding.GetChars*?displayProperty=nameWithType method. To decode a byte array into a string, you call the System.Text.Encoding.GetString* method. If you want to determine how many characters are needed to store the decoded bytes before performing the decoding, you can call the System.Text.Encoding.GetCharCount* method.

The following example encodes three strings and then decodes them into a single array of characters. It maintains an index that indicates the starting position in the character array for the next set of decoded characters. It calls the System.Text.ASCIIEncoding.GetCharCount* method to ensure that the character array is large enough to accommodate all the decoded characters. It then calls the System.Text.ASCIIEncoding.GetChars%28System.Byte%5B%5D%2CSystem.Int32%2CSystem.Int32%2CSystem.Char%5B%5D%2CSystem.Int32%29?displayProperty=nameWithType method to decode the byte array.

    using System;
    using System.Text;

    public class Example
    {
       public static void Main()
       {
          string[] strings = { "This is the first sentence. ",
                               "This is the second sentence. ",
                               "This is the third sentence. " };
          Encoding asciiEncoding = Encoding.ASCII;
          // Array to hold encoded bytes.
          byte[] bytes;
          // Array to hold decoded characters.
          char[] chars = new char[50];
          // Create index for current position of character array.
          int index = 0;

          foreach (var stringValue in strings) {
             Console.WriteLine($"String to Encode: {stringValue}");
             // Encode the string to a byte array.
             bytes = asciiEncoding.GetBytes(stringValue);
             // Display the encoded bytes.
             Console.Write("Encoded bytes: ");
             for (int ctr = 0; ctr < bytes.Length; ctr++)
                Console.Write(" {0}{1:X2}",
                              ctr % 20 == 0 ? Environment.NewLine : "",
                              bytes[ctr]);
             Console.WriteLine();

             // Decode the bytes to a single character array.
             int count = asciiEncoding.GetCharCount(bytes);
             if (count + index >=  chars.Length)
                Array.Resize(ref chars, chars.Length + 50);

             int written = asciiEncoding.GetChars(bytes, 0,
                                                  bytes.Length,
                                                  chars, index);
             index = index + written;
             Console.WriteLine();
          }

          // Instantiate a single string containing the characters.
          string decodedString = new string(chars, 0, index - 1);
          Console.WriteLine("Decoded string: ");
          Console.WriteLine(decodedString);
       }
    }
