The encoding and decoding methods of a class derived from System.Text.Encoding are designed to work on a complete set of data; that is, all the data to be encoded or decoded is supplied in a single method call. However, in some cases, data is available in a stream, and the data to be encoded or decoded may be available only from separate read operations. This requires the encoding or decoding operation to remember any saved state from its previous invocation. Methods of classes derived from System.Text.Encoder and System.Text.Decoder are able to handle encoding and decoding operations that span multiple method calls.

An System.Text.Encoder object for a particular encoding is available from that encoding's System.Text.Encoding.GetEncoder?displayProperty=nameWithType property. A System.Text.Decoder object for a particular encoding is available from that encoding's System.Text.Encoding.GetDecoder?displayProperty=nameWithType property. For decoding operations, note that classes derived from System.Text.Decoder include a System.Text.Decoder.GetChars*?displayProperty=nameWithType method, but they do not have a method that corresponds to System.Text.Encoding.GetString*?displayProperty=nameWithType.

The following example illustrates the difference between using the System.Text.Encoding.GetString*?displayProperty=nameWithType and System.Text.Decoder.GetChars*?displayProperty=nameWithType methods for decoding a Unicode byte array. The example encodes a string that contains some Unicode characters to a file, and then uses the two decoding methods to decode them ten bytes at a time. Because a surrogate pair occurs in the tenth and eleventh bytes, it is decoded in separate method calls. As the output shows, the System.Text.Encoding.GetString*?displayProperty=nameWithType method is not able to correctly decode the bytes and instead replaces them with U+FFFD (REPLACEMENT CHARACTER). On the other hand, the System.Text.Decoder.GetChars*?displayProperty=nameWithType method is able to successfully decode the byte array to get the original string.

    using System;
    using System.IO;
    using System.Text;

    public class Example
    {
       public static void Main()
       {
          // Use default replacement fallback for invalid encoding.
          UnicodeEncoding enc = new UnicodeEncoding(true, false, false);

          // Define a string with various Unicode characters.
          string str1 = "AB YZ 19 \uD800\udc05 \u00e4";
          str1 += "Unicode characters. \u00a9 \u010C s \u0062\u0308";
          Console.WriteLine("Created original string...\n");

          // Convert string to byte array.
          byte[] bytes = enc.GetBytes(str1);

          FileStream fs = File.Create(@".\characters.bin");
          BinaryWriter bw = new BinaryWriter(fs);
          bw.Write(bytes);
          bw.Close();

          // Read bytes from file.
          FileStream fsIn = File.OpenRead(@".\characters.bin");
          BinaryReader br = new BinaryReader(fsIn);

          const int count = 10;            // Number of bytes to read at a time.
          byte[] bytesRead = new byte[10]; // Buffer (byte array).
          int read;                        // Number of bytes actually read.
          string str2 = String.Empty;      // Decoded string.

          // Try using Encoding object for all operations.
          do {
             read = br.Read(bytesRead, 0, count);
             str2 += enc.GetString(bytesRead, 0, read);
          } while (read == count);
          br.Close();
          Console.WriteLine("Decoded string using UnicodeEncoding.GetString()...");
          CompareForEquality(str1, str2);
          Console.WriteLine();

          // Use Decoder for all operations.
          fsIn = File.OpenRead(@".\characters.bin");
          br = new BinaryReader(fsIn);
          Decoder decoder = enc.GetDecoder();
          char[] chars = new char[50];
          int index = 0;                   // Next character to write in array.
          int written = 0;                 // Number of chars written to array.
          do {
             read = br.Read(bytesRead, 0, count);
             if (index + decoder.GetCharCount(bytesRead, 0, read) - 1 >= chars.Length)
                Array.Resize(ref chars, chars.Length + 50);

             written = decoder.GetChars(bytesRead, 0, read, chars, index);
             index += written;
          } while (read == count);
          br.Close();
          // Instantiate a string with the decoded characters.
          string str3 = new String(chars, 0, index);
          Console.WriteLine("Decoded string using UnicodeEncoding.Decoder.GetString()...");
          CompareForEquality(str1, str3);
       }

       private static void CompareForEquality(string original, string decoded)
       {
          bool result = original.Equals(decoded);
          Console.WriteLine($"original = decoded: {original.Equals(decoded, StringComparison.Ordinal)}");
          if (!result) {
             Console.WriteLine("Code points in original string:");
             foreach (var ch in original)
                Console.Write("{0} ", Convert.ToUInt16(ch).ToString("X4"));
             Console.WriteLine();

             Console.WriteLine("Code points in decoded string:");
             foreach (var ch in decoded)
                Console.Write("{0} ", Convert.ToUInt16(ch).ToString("X4"));
             Console.WriteLine();
          }
       }
    }
