Note

You can also implement a replacement class for an encoding. For more information, see the Implementing a Custom Fallback Strategy section.

In addition to QUESTION MARK (U+003F), the Unicode REPLACEMENT CHARACTER (U+FFFD) is commonly used as a replacement string, particularly when decoding byte sequences that cannot be successfully translated into Unicode characters. However, you are free to choose any replacement string, and it can contain multiple characters.

Exception Fallback

Instead of providing a best-fit fallback or a replacement string, an encoder can throw an System.Text.EncoderFallbackException if it is unable to encode a set of characters, and a decoder can throw a System.Text.DecoderFallbackException if it is unable to decode a byte array. To throw an exception in encoding and decoding operations, you supply an System.Text.EncoderExceptionFallback object and a System.Text.DecoderExceptionFallback object, respectively, to the System.Text.Encoding.GetEncoding%28System.String%2CSystem.Text.EncoderFallback%2CSystem.Text.DecoderFallback%29?displayProperty=nameWithType method. The following example illustrates exception fallback with the System.Text.ASCIIEncoding class.

    using System;
    using System.Text;

    public class Example
    {
       public static void Main()
       {
          Encoding enc = Encoding.GetEncoding("us-ascii",
                                              new EncoderExceptionFallback(),
                                              new DecoderExceptionFallback());

          string str1 = "\u24C8 \u2075 \u221E";
          Console.WriteLine(str1);
          foreach (var ch in str1)
             Console.Write("{0} ", Convert.ToUInt16(ch).ToString("X4"));

          Console.WriteLine("\n");

          // Encode the original string using the ASCII encoder.
          byte[] bytes = {};
          try {
             bytes = enc.GetBytes(str1);
             Console.Write("Encoded bytes: ");
             foreach (var byt in bytes)
                Console.Write("{0:X2} ", byt);

             Console.WriteLine();
          }
          catch (EncoderFallbackException e) {
             Console.Write("Exception: ");
             if (e.IsUnknownSurrogate())
                Console.WriteLine($"Unable to encode surrogate pair 0x{Convert.ToUInt16(e.CharUnknownHigh):X4} 0x{Convert.ToUInt16(e.CharUnknownLow):X3} at index {e.Index}.");
             else
                Console.WriteLine($"Unable to encode 0x{Convert.ToUInt16(e.CharUnknown):X4} at index {e.Index}.");
             return;
          }
          Console.WriteLine();

          // Decode the ASCII bytes.
          try {
             string str2 = enc.GetString(bytes);
             Console.WriteLine($"Round-trip: {str1.Equals(str2)}");
             if (!str1.Equals(str2)) {
                Console.WriteLine(str2);
                foreach (var ch in str2)
                   Console.Write("{0} ", Convert.ToUInt16(ch).ToString("X4"));

                Console.WriteLine();
             }
          }
          catch (DecoderFallbackException e) {
             Console.Write("Unable to decode byte(s) ");
             foreach (byte unknown in e.BytesUnknown)
                Console.Write("0x{0:X2} ");

             Console.WriteLine($"at index {e.Index}");
          }
       }
    }
    // The example displays the following output:
    //       Ⓢ ⁵ ∞
    //       24C8 0020 2075 0020 221E
    //
    //       Exception: Unable to encode 0x24C8 at index 0.

