The following code defines the CustomMapperFallbackBuffer class, which is derived from System.Text.EncoderFallbackBuffer. The dictionary that contains best-fit mappings and that is defined in the CustomMapper instance is available from its class constructor. Its Fallback method returns true if any of the Unicode characters that the ASCII encoder cannot encode are defined in the mapping dictionary; otherwise, it returns false. For each fallback, the private count variable indicates the number of characters that remain to be returned, and the private index variable indicates the position in the string buffer, charsToReturn, of the next character to return.

    public class CustomMapperFallbackBuffer : EncoderFallbackBuffer
    {
       int count = -1;                   // Number of characters to return
       int index = -1;                   // Index of character to return
       CustomMapper fb;
       string charsToReturn;

       public CustomMapperFallbackBuffer(CustomMapper fallback)
       {
          this.fb = fallback;
       }

       public override bool Fallback(char charUnknownHigh, char charUnknownLow, int index)
       {
          // Do not try to map surrogates to ASCII.
          return false;
       }

       public override bool Fallback(char charUnknown, int index)
       {
          // Return false if there are already characters to map.
          if (count >= 1) return false;

          // Determine number of characters to return.
          charsToReturn = String.Empty;

          ushort key = Convert.ToUInt16(charUnknown);
          if (fb.mapping.ContainsKey(key)) {
             byte[] bytes = BitConverter.GetBytes(fb.mapping[key]);
             int ctr = 0;
             foreach (var byt in bytes) {
                if (byt > 0) {
                   ctr++;
                   charsToReturn += (char) byt;
                }
             }
             count = ctr;
          }
          else {
             // Return default.
             charsToReturn = fb.DefaultString;
             count = 1;
          }
          this.index = charsToReturn.Length - 1;

          return true;
       }

       public override char GetNextChar()
       {
          // We'll return a character if possible, so subtract from the count of chars to return.
          count--;
          // If count is less than zero, we've returned all characters.
          if (count < 0)
             return '\u0000';

          this.index--;
          return charsToReturn[this.index + 1];
       }

       public override bool MovePrevious()
       {
          // Original: if count >= -1 and pos >= 0
          if (count >= -1) {
             count++;
             return true;
          }
          else {
             return false;
          }
       }

       public override int Remaining
       {
          get { return count < 0 ? 0 : count; }
       }

       public override void Reset()
       {
          count = -1;
          index = -1;
       }
    }

