The following code then instantiates the CustomMapper object and passes an instance of it to the System.Text.Encoding.GetEncoding%28System.String%2CSystem.Text.EncoderFallback%2CSystem.Text.DecoderFallback%29?displayProperty=nameWithType method. The output indicates that the best-fit fallback implementation successfully handles the three non-ASCII characters in the original string.

    using System;
    using System.Collections.Generic;
    using System.Text;

    class Program
    {
       static void Main()
       {
          Encoding enc = Encoding.GetEncoding("us-ascii", new CustomMapper(), new DecoderExceptionFallback());

          string str1 = "\u24C8 \u2075 \u221E";
          Console.WriteLine(str1);
          for (int ctr = 0; ctr <= str1.Length - 1; ctr++) {
             Console.Write("{0} ", Convert.ToUInt16(str1[ctr]).ToString("X4"));
             if (ctr == str1.Length - 1)
                Console.WriteLine();
          }
          Console.WriteLine();

          // Encode the original string using the ASCII encoder.
          byte[] bytes = enc.GetBytes(str1);
          Console.Write("Encoded bytes: ");
          foreach (var byt in bytes)
             Console.Write("{0:X2} ", byt);

          Console.WriteLine("\n");

          // Decode the ASCII bytes.
          string str2 = enc.GetString(bytes);
          Console.WriteLine($"Round-trip: {str1.Equals(str2)}");
          if (!str1.Equals(str2)) {
             Console.WriteLine(str2);
             foreach (var ch in str2)
                Console.Write("{0} ", Convert.ToUInt16(ch).ToString("X4"));

             Console.WriteLine();
          }
       }
    }

