       string fmt = new String('d', ctr) + @"\.hh\:mm\:ss";
       Console.WriteLine($"{fmt} --> {ts1.ToString(fmt)}");
       Console.WriteLine($"{fmt} --> {ts2.ToString(fmt)}");
       Console.WriteLine();
    }
