    If TimeSpan.TryParseExact(value, "%h", Nothing, interval) Then
        Console.WriteLine(interval.ToString("c"))
    Else
        Console.WriteLine("Unable to convert '{0}' to a time interval",
                          value)
    End If
    ' The example displays the following output:
    '       08:00:00

