• Right-to-left matching, which is specified by supplying the System.Text.RegularExpressions.RegexOptions.RightToLeft?displayProperty=nameWithType option to a System.Text.RegularExpressions.Regex class constructor or static instance matching method. This feature is useful when searching from right to left instead of from left to right, or in cases where it is more efficient to begin a match at the right part of the pattern instead of the left. As the following example illustrates, using right-to-left matching can change the behavior of greedy quantifiers. The example conducts two searches for a sentence that ends in a number. The left-to-right search that uses the greedy quantifier + matches one of the six digits in the sentence, whereas the right-to-left search matches all six digits. For a description of the regular expression pattern, see the example that illustrates lazy quantifiers earlier in this section.

    using System;
    using System.Text.RegularExpressions;

    public class Example
    {
        public static void Main()
        {
            string greedyPattern = @".+(\d+)\.";
            string input = "This sentence ends with the number 107325.";
            Match match;

            // Match from left-to-right using lazy quantifier .+?.
            match = Regex.Match(input, greedyPattern);
            if (match.Success)
                Console.WriteLine($"Number at end of sentence (left-to-right): {match.Groups[1].Value}");
            else
                Console.WriteLine($"{greedyPattern} finds no match.");

            // Match from right-to-left using greedy quantifier .+.
            match = Regex.Match(input, greedyPattern, RegexOptions.RightToLeft);
            if (match.Success)
                Console.WriteLine($"Number at end of sentence (right-to-left): {match.Groups[1].Value}");
            else
                Console.WriteLine($"{greedyPattern} finds no match.");
        }
    }
    // The example displays the following output:
    //       Number at end of sentence (left-to-right): 5
    //       Number at end of sentence (right-to-left): 107325

