            Dim pattern As String = "\b\w+\b(?!\p{P})"
            Dim input As String = "Disconnected, disjointed thoughts in a sentence fragment."
            For Each match As Match In Regex.Matches(input, pattern)
                Console.WriteLine(match.Value)
            Next
        End Sub
    End Module
