            Console.WriteLine(String.Format(New TelephoneFormatter, "{0}", 911))
            Console.WriteLine(String.Format(New TelephoneFormatter, "{0}", 8490216))
            ' <Snippet3>
            Console.WriteLine(String.Format(New TelephoneFormatter, "{0}", 4257884748))
            ' </Snippet3>

            Console.WriteLine(String.Format(New TelephoneFormatter, "{0:N}", 0))
            Console.WriteLine(String.Format(New TelephoneFormatter, "{0:N}", 911))
            Console.WriteLine(String.Format(New TelephoneFormatter, "{0:N}", 8490216))
            ' <Snippet2>
            Console.WriteLine(String.Format(New TelephoneFormatter, "{0:N}", 4257884748))
            ' </Snippet2>

            Console.WriteLine(String.Format(New TelephoneFormatter, "{0:I}", 4257884748))
        End Sub
    End Module

The custom numeric format provider can be used only with the System.String.Format%28System.IFormatProvider%2CSystem.String%2CSystem.Object%5B%5D%29?displayProperty=nameWithType method. The other overloads of numeric formatting methods (such as ToString) that have a parameter of type System.IFormatProvider all pass the System.IFormatProvider.GetFormat*?displayProperty=nameWithType implementation a System.Type object that represents the System.Globalization.NumberFormatInfo type. In return, they expect the method to return a System.Globalization.NumberFormatInfo object. If it does not, the custom numeric format provider is ignored, and the System.Globalization.NumberFormatInfo object for the current culture is used in its place. In the example, the TelephoneFormatter.GetFormat method handles the possibility that it may be inappropriately passed to a numeric formatting method by examining the method parameter and returning null if it represents a type other than System.ICustomFormatter.

If a custom numeric format provider supports a set of format specifiers, make sure you provide a default behavior if no format specifier is supplied in the format item used in the System.String.Format%28System.IFormatProvider%2CSystem.String%2CSystem.Object%5B%5D%29?displayProperty=nameWithType method call. In the example, "N" is the default format specifier. This allows for a number to be converted to a formatted telephone number by providing an explicit format specifier. The following example illustrates such a method call.

    Console.WriteLine(String.Format(new TelephoneFormatter(), "{0:N}", 4257884748));

    Console.WriteLine(String.Format(New TelephoneFormatter, "{0:N}", 4257884748))

But it also allows the conversion to occur if no format specifier is present. The following example illustrates such a method call.

    Console.WriteLine(String.Format(new TelephoneFormatter(), "{0}", 4257884748));

    Console.WriteLine(String.Format(New TelephoneFormatter, "{0}", 4257884748))

If no default format specifier is defined, your implementation of the System.ICustomFormatter.Format*?displayProperty=nameWithType method should include code such as the following so that .NET can provide formatting that your code does not support.

    if (arg is IFormattable)
       s = ((IFormattable)arg).ToString(format, formatProvider);
    else if (arg != null)
       s = arg.ToString();

    If TypeOf (arg) Is IFormattable Then
        s = DirectCast(arg, IFormattable).ToString(fmt, formatProvider)
    ElseIf arg IsNot Nothing Then
        s = arg.ToString()
    End If

In the case of this example, the method that implements System.ICustomFormatter.Format*?displayProperty=nameWithType is intended to serve as a callback method for the System.String.Format%28System.IFormatProvider%2CSystem.String%2CSystem.Object%5B%5D%29?displayProperty=nameWithType method. Therefore, it examines the formatProvider parameter to determine whether it contains a reference to the current TelephoneFormatter object. However, the method can also be called directly from code. In that case, you can use the formatProvider parameter to provide a System.Globalization.CultureInfo or System.Globalization.NumberFormatInfo object that supplies culture-specific formatting information.

How to: Display Dates in Non-Gregorian Calendars

The System.DateTime and System.DateTimeOffset types use the Gregorian calendar as their default calendar. This means that calling a date and time value's ToString method displays the string representation of that date and time in the Gregorian calendar, even if that date and time was created using another calendar. This is illustrated in the following example, which uses two different ways to create a date and time value with the Persian calendar, but still displays those date and time values in the Gregorian calendar when it calls the System.DateTime.ToString* method. This example reflects two commonly used but incorrect techniques for displaying the date in a particular calendar.

    PersianCalendar persianCal = new PersianCalendar();

    DateTime persianDate = persianCal.ToDateTime(1387, 3, 18, 12, 0, 0, 0);
    Console.WriteLine(persianDate.ToString());

    persianDate = new DateTime(1387, 3, 18, persianCal);
    Console.WriteLine(persianDate.ToString());
    // The example displays the following output to the console:
    //       6/7/2008 12:00:00 PM
    //       6/7/2008 12:00:00 AM

    Dim persianCal As New PersianCalendar()

    Dim persianDate As Date = persianCal.ToDateTime(1387, 3, 18, _
                                                    12, 0, 0, 0)
    Console.WriteLine(persianDate.ToString())

    persianDate = New DateTime(1387, 3, 18, persianCal)
    Console.WriteLine(persianDate.ToString())
    ' The example displays the following output to the console:
    '       6/7/2008 12:00:00 PM
    '       6/7/2008 12:00:00 AM

Two different techniques can be used to display the date in a particular calendar. The first requires that the calendar be the default calendar for a particular culture. The second can be used with any calendar.

To display the date for a culture's default calendar

• Instantiate a calendar object derived from the System.Globalization.Calendar class that represents the calendar to be used.

• Instantiate a System.Globalization.CultureInfo object representing the culture whose formatting will be used to display the date.

• Call the System.Array.Exists*?displayProperty=nameWithType method to determine whether the calendar object is a member of the array returned by the System.Globalization.CultureInfo.OptionalCalendars?displayProperty=nameWithType property. This indicates that the calendar can serve as the default calendar for the System.Globalization.CultureInfo object. If it is not a member of the array, follow the instructions in the "To Display the Date in Any Calendar" section.

• Assign the calendar object to the System.Globalization.DateTimeFormatInfo.Calendar property of the System.Globalization.DateTimeFormatInfo object returned by the System.Globalization.CultureInfo.DateTimeFormat?displayProperty=nameWithType property.

Note

The System.Globalization.CultureInfo class also has a System.Globalization.CultureInfo.Calendar property. However, it is read-only and constant; it does not change to reflect the new default calendar assigned to the System.Globalization.DateTimeFormatInfo.Calendar?displayProperty=nameWithType property.

• Call either the System.DateTime.ToString* or the System.DateTime.ToString* method, and pass it the System.Globalization.CultureInfo object whose default calendar was modified in the previous step.

To display the date in any calendar

• Instantiate a calendar object derived from the System.Globalization.Calendar class that represents the calendar to be used.

• Determine which date and time elements should appear in the string representation of the date and time value.

• For each date and time element that you want to display, call the calendar object's Get… method. The following methods are available:

• System.Globalization.Calendar.GetYear*, to display the year in the appropriate calendar.

• System.Globalization.Calendar.GetMonth*, to display the month in the appropriate calendar.

• System.Globalization.Calendar.GetDayOfMonth*, to display the number of the day of the month in the appropriate calendar.

• System.Globalization.Calendar.GetHour*, to display the hour of the day in the appropriate calendar.

• System.Globalization.Calendar.GetMinute*, to display the minutes in the hour in the appropriate calendar.

• System.Globalization.Calendar.GetSecond*, to display the seconds in the minute in the appropriate calendar.

• System.Globalization.Calendar.GetMilliseconds*, to display the milliseconds in the second in the appropriate calendar.

Example

The example displays a date using two different calendars. It displays the date after defining the Hijri calendar as the default calendar for the ar-JO culture, and displays the date using the Persian calendar, which is not supported as an optional calendar by the fa-IR culture.

    using System;
    using System.Globalization;

    public class CalendarDates
    {
       public static void Main()
       {
          HijriCalendar hijriCal = new HijriCalendar();
          CalendarUtility hijriUtil = new CalendarUtility(hijriCal);
          DateTime dateValue1 = new DateTime(1429, 6, 29, hijriCal);
          DateTimeOffset dateValue2 = new DateTimeOffset(dateValue1,
                                      TimeZoneInfo.Local.GetUtcOffset(dateValue1));
          CultureInfo jc = CultureInfo.CreateSpecificCulture("ar-JO");

          // Display the date using the Gregorian calendar.
          Console.WriteLine($"Using the system default culture: {dateValue1.ToString("d")}");
          // Display the date using the ar-JO culture's original default calendar.
          Console.WriteLine($"Using the ar-JO culture's original default calendar: {dateValue1.ToString("d", jc)}");
          // Display the date using the Hijri calendar.
          Console.WriteLine("Using the ar-JO culture with Hijri as the default calendar:");
          // Display a Date value.
          Console.WriteLine(hijriUtil.DisplayDate(dateValue1, jc));
          // Display a DateTimeOffset value.
          Console.WriteLine(hijriUtil.DisplayDate(dateValue2, jc));

          Console.WriteLine();

          PersianCalendar persianCal = new PersianCalendar();
          CalendarUtility persianUtil = new CalendarUtility(persianCal);
          CultureInfo ic = CultureInfo.CreateSpecificCulture("fa-IR");

          // Display the date using the ir-FA culture's default calendar.
          Console.WriteLine($"Using the ir-FA culture's default calendar: {dateValue1.ToString("d", ic)}");
          // Display a Date value.
          Console.WriteLine(persianUtil.DisplayDate(dateValue1, ic));
          // Display a DateTimeOffset value.
          Console.WriteLine(persianUtil.DisplayDate(dateValue2, ic));
       }
    }

    public class CalendarUtility
    {
       private Calendar thisCalendar;
       private CultureInfo targetCulture;

       public CalendarUtility(Calendar cal)
       {
          this.thisCalendar = cal;
       }

       private bool CalendarExists(CultureInfo culture)
       {
          this.targetCulture = culture;
          return Array.Exists(this.targetCulture.OptionalCalendars,
                              this.HasSameName);
       }

       private bool HasSameName(Calendar cal)
       {
          if (cal.ToString() == thisCalendar.ToString())
             return true;
          else
             return false;
       }

       public string DisplayDate(DateTime dateToDisplay, CultureInfo culture)
       {
          DateTimeOffset displayOffsetDate = dateToDisplay;
          return DisplayDate(displayOffsetDate, culture);
       }

       public string DisplayDate(DateTimeOffset dateToDisplay,
                                 CultureInfo culture)
       {
          string specifier = "yyyy/MM/dd";

          if (this.CalendarExists(culture))
          {
             Console.WriteLine($"Displaying date in supported {this.thisCalendar.GetType().Name} calendar...");
             culture.DateTimeFormat.Calendar = this.thisCalendar;
             return dateToDisplay.ToString(specifier, culture);
          }
          else
          {
             Console.WriteLine($"Displaying date in unsupported {thisCalendar.GetType().Name} calendar...");

             string separator = targetCulture.DateTimeFormat.DateSeparator;

             return thisCalendar.GetYear(dateToDisplay.DateTime).ToString("0000") +
                    separator +
                    thisCalendar.GetMonth(dateToDisplay.DateTime).ToString("00") +
                    separator +
                    thisCalendar.GetDayOfMonth(dateToDisplay.DateTime).ToString("00");
          }
       }
    }
