    //    Matches:
    //       1 at position 2
    //       2 at position 5
    //       3 at position 8
    //       4 at position 11
    //       5 at position 14
    //    Input string:  aa1bb2cc3dd4ee5
    //    Output string: aaaabbaa1bbccaa1bb2ccddaa1bb2cc3ddeeaa1bb2cc3dd4ee

