            Dim input As String = "16.32" + vbCrLf + "194.03" + vbCrLf + "1,903,672.08"

            For Each match As Match In Regex.Matches(input, pattern)
                Console.WriteLine(match.Result("$$ $&"))
            Next
        End Sub
