The lower level System.Text.Json.Utf8JsonWriter writes System.DateTime and System.DateTimeOffset data:

    using System.Text;
    using System.Text.Json;

    public class Example
    {
        public static void Main(string[] args)
        {
            JsonWriterOptions options = new JsonWriterOptions
            {
                Indented = true
            };

            using (MemoryStream stream = new MemoryStream())
            {
                using (Utf8JsonWriter writer = new Utf8JsonWriter(stream, options))
                {
                    writer.WriteStartObject();
                    writer.WriteString("date", DateTimeOffset.UtcNow);
                    writer.WriteNumber("temp", 42);
                    writer.WriteEndObject();
                }

                string json = Encoding.UTF8.GetString(stream.ToArray());
                Console.WriteLine(json);
            }
        }
    }

    // The example output similar to the following:
    // {
    //     "date": "2019-07-26T00:00:00+00:00",
    //     "temp": 42
    // }

System.Text.Json.Utf8JsonReader parses System.DateTime and System.DateTimeOffset data:

    using System.Text;
    using System.Text.Json;

    public class Example
    {
        public static void Main(string[] args)
        {
            byte[] utf8Data = Encoding.UTF8.GetBytes(@"""2019-07-26T00:00:00""");

            Utf8JsonReader json = new Utf8JsonReader(utf8Data);
            while (json.Read())
            {
                if (json.TokenType == JsonTokenType.String)
                {
                    Console.WriteLine(json.TryGetDateTime(out DateTime datetime));
                    Console.WriteLine(datetime);
                    Console.WriteLine(json.GetDateTime());
                }
            }
        }
    }

    // The example displays output similar to the following:
    // True
    // 7/26/2019 12:00:00 AM
    // 7/26/2019 12:00:00 AM

If you attempt to read non-compliant formats with System.Text.Json.Utf8JsonReader, it throws a System.FormatException:

    using System.Text;
    using System.Text.Json;

    public class Example
    {
        public static void Main(string[] args)
        {
            byte[] utf8Data = Encoding.UTF8.GetBytes(@"""2019/07/26 00:00:00""");

            Utf8JsonReader json = new Utf8JsonReader(utf8Data);
            while (json.Read())
            {
                if (json.TokenType == JsonTokenType.String)
                {
                    Console.WriteLine(json.TryGetDateTime(out DateTime datetime));
                    Console.WriteLine(datetime);

                    DateTime _ = json.GetDateTime();
                }
            }
        }
    }

    // The example displays the following output:
    // False
    // 1/1/0001 12:00:00 AM
    // Unhandled exception. System.FormatException: The JSON value is not in a supported DateTime format.
    //     at System.Text.Json.Utf8JsonReader.GetDateTime()

Serialize DateOnly and TimeOnly properties

Starting in .NET 7, System.Text.Json supports serializing and deserializing System.DateOnly and System.TimeOnly types. Consider the following object:

    sealed file record Appointment(
        Guid Id,
        string Description,
        DateOnly Date,
        TimeOnly StartTime,
        TimeOnly EndTime);

The following example serializes an Appointment object, displays the resulting JSON, and then deserializes it back into a new instance of the Appointment type. Finally, the original and newly deserialized instances are compared for equality and the results are written to the console:

    Appointment originalAppointment = new(
        Id: Guid.NewGuid(),
        Description: "Take dog to veterinarian.",
        Date: new DateOnly(2002, 1, 13),
        StartTime: new TimeOnly(5,15),
        EndTime: new TimeOnly(5, 45));
    string serialized = JsonSerializer.Serialize(originalAppointment);

    Console.WriteLine($"Resulting JSON: {serialized}");

    Appointment deserializedAppointment =
        JsonSerializer.Deserialize<Appointment>(serialized)!;

    bool valuesAreTheSame = originalAppointment == deserializedAppointment;
    Console.WriteLine($"""
        Original record has the same values as the deserialized record: {valuesAreTheSame}
        """);

In the preceding code:

• An Appointment object is instantiated and assigned to the appointment variable.

• The appointment instance is serialized to JSON using System.Text.Json.JsonSerializer.Serialize*?displayProperty=nameWithType.

• The resulting JSON is written to the console.

• The JSON is deserialized back into a new instance of the Appointment type using System.Text.Json.JsonSerializer.Deserialize*?displayProperty=nameWithType.

• The original and newly deserialized instances are compared for equality.

• The result of the comparison is written to the console.

Custom support for System.DateTime and System.DateTimeOffset

When using System.Text.Json.JsonSerializer

If you want the serializer to perform custom parsing or formatting, you can implement custom converters. The following sections show a few examples:

• DateTime(Offset).Parse and DateTime(Offset).ToString

• Utf8Parser and Utf8Formatter

• Use DateTime(Offset).Parse as a fallback

• Use Unix epoch date format

DateTime(Offset).Parse and DateTime(Offset).ToString

If you can't determine the formats of your input System.DateTime or System.DateTimeOffset text representations, you can use the DateTime(Offset).Parse method in your converter read logic. This method allows you to use .NET's extensive support for parsing various System.DateTime and System.DateTimeOffset text formats, including non-ISO 8601 strings and ISO 8601 formats that don't conform to the extended ISO 8601-1:2019 profile. This approach is less performant than using the serializer's native implementation.

For serializing, you can use the DateTime(Offset).ToString method in your converter write logic. This method allows you to write System.DateTime and System.DateTimeOffset values using any of the standard date and time formats, and the custom date and time formats. This approach is also less performant than using the serializer's native implementation.

    using System.Diagnostics;
    using System.Text.Json;
    using System.Text.Json.Serialization;
    using System.Text.RegularExpressions;

    namespace DateTimeConverterExamples;

    public class DateTimeConverterUsingDateTimeParse : JsonConverter<DateTime>
    {
        public override DateTime Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            Debug.Assert(typeToConvert == typeof(DateTime));
            return DateTime.Parse(reader.GetString() ?? string.Empty);
        }

        public override void Write(Utf8JsonWriter writer, DateTime value, JsonSerializerOptions options)
        {
            writer.WriteStringValue(value.ToString());
        }
    }

    class Program
    {
        private static void ParseDateTimeWithDefaultOptions()
        {
            DateTime _ = JsonSerializer.Deserialize<DateTime>(@"""04-10-2008 6:30 AM""");
        }

        private static void FormatDateTimeWithDefaultOptions()
        {
            Console.WriteLine(JsonSerializer.Serialize(DateTime.Parse("04-10-2008 6:30 AM -4")));
        }

        private static void ProcessDateTimeWithCustomConverter()
        {
            JsonSerializerOptions options = new JsonSerializerOptions();
            options.Converters.Add(new DateTimeConverterUsingDateTimeParse());

            string testDateTimeStr = "04-10-2008 6:30 AM";
            string testDateTimeJson = @"""" + testDateTimeStr + @"""";

            DateTime resultDateTime = JsonSerializer.Deserialize<DateTime>(testDateTimeJson, options);
            Console.WriteLine(resultDateTime);

            string resultDateTimeJson = JsonSerializer.Serialize(DateTime.Parse(testDateTimeStr), options);
            Console.WriteLine(Regex.Unescape(resultDateTimeJson));
        }

        static void Main(string[] args)
        {
            // Parsing non-compliant format as DateTime fails by default.
            try
            {
                ParseDateTimeWithDefaultOptions();
            }
            catch (JsonException e)
            {
                Console.WriteLine(e.Message);
            }

            // Formatting with default options prints according to extended ISO 8601 profile.
            FormatDateTimeWithDefaultOptions();

            // Using converters gives you control over the serializers parsing and formatting.
            ProcessDateTimeWithCustomConverter();
        }
    }

    // The example displays output similar to the following:
    // The JSON value could not be converted to System.DateTime. Path: $ | LineNumber: 0 | BytePositionInLine: 20.
    // "2008-04-10T06:30:00-04:00"
    // 4/10/2008 6:30:00 AM
    // "4/10/2008 6:30:00 AM"

Note

When implementing [System.Text.Json.Serialization.JsonConverter1](xref:System.Text.Json.Serialization.JsonConverter1), and T is System.DateTime, the typeToConvert parameter will always be typeof(DateTime). The parameter is useful for handling polymorphic cases and when using generics to get typeof(T) in a performant way.

System.Buffers.Text.Utf8Parser and System.Buffers.Text.Utf8Formatter

You can use fast UTF-8-based parsing and formatting methods in your converter logic if your input System.DateTime or System.DateTimeOffset text representations are compliant with one of the "R", "l", "O", or "G" standard date and time format strings, or you want to write according to one of these formats. This approach is much faster than using DateTime(Offset).Parse and DateTime(Offset).ToString.

The following example shows a custom converter that serializes and deserializes System.DateTime values according to the "R" standard format:

    using System.Buffers;
    using System.Buffers.Text;
    using System.Diagnostics;
    using System.Text.Json;
    using System.Text.Json.Serialization;

    namespace DateTimeConverterExamples;

    // This converter reads and writes DateTime values according to the "R" standard format specifier:
    // https://learn.microsoft.com/dotnet/standard/base-types/standard-date-and-time-format-strings#the-rfc1123-r-r-format-specifier.
    public class DateTimeConverterForCustomStandardFormatR : JsonConverter<DateTime>
    {
        public override DateTime Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            Debug.Assert(typeToConvert == typeof(DateTime));

            if (Utf8Parser.TryParse(reader.ValueSpan, out DateTime value, out _, 'R'))
            {
                return value;
            }

            throw new FormatException();
        }

        public override void Write(Utf8JsonWriter writer, DateTime value, JsonSerializerOptions options)
        {
            // The "R" standard format will always be 29 bytes.
            Span<byte> utf8Date = stackalloc byte[29];

            bool result = Utf8Formatter.TryFormat(value, utf8Date, out _, new StandardFormat('R'));
            Debug.Assert(result);

            writer.WriteStringValue(utf8Date);
        }
    }

    class Program
    {
        private static void ParseDateTimeWithDefaultOptions()
        {
            DateTime _ = JsonSerializer.Deserialize<DateTime>(@"""Thu, 25 Jul 2019 13:36:07 GMT""");
        }

        private static void ProcessDateTimeWithCustomConverter()
        {
            JsonSerializerOptions options = new JsonSerializerOptions();
            options.Converters.Add(new DateTimeConverterForCustomStandardFormatR());

            string testDateTimeStr = "Thu, 25 Jul 2019 13:36:07 GMT";
            string testDateTimeJson = @"""" + testDateTimeStr + @"""";

            DateTime resultDateTime = JsonSerializer.Deserialize<DateTime>(testDateTimeJson, options);
            Console.WriteLine(resultDateTime);

            Console.WriteLine(JsonSerializer.Serialize(DateTime.Parse(testDateTimeStr), options));
        }

        static void Main(string[] args)
        {
            // Parsing non-compliant format as DateTime fails by default.
            try
            {
                ParseDateTimeWithDefaultOptions();
            }
            catch (JsonException e)
            {
                Console.WriteLine(e.Message);
            }

            // Using converters gives you control over the serializers parsing and formatting.
            ProcessDateTimeWithCustomConverter();
        }
    }

    // The example displays output similar to the following:
    // The JSON value could not be converted to System.DateTime.Path: $ | LineNumber: 0 | BytePositionInLine: 31.
    // 7/25/2019 1:36:07 PM
    // "Thu, 25 Jul 2019 09:36:07 GMT"

Note

The "R" standard format will always be 29 characters long.

The "l" (lowercase "L") format isn't documented with the other standard date and time format strings because it's supported only by the Utf8Parser and Utf8Formatter types. The format is lowercase RFC 1123 (a lowercase version of the "R" format). For example, "thu, 25 jul 2019 06:36:07 gmt".

Use DateTime(Offset).Parse as a fallback

If you generally expect your input System.DateTime or System.DateTimeOffset data to conform to the extended ISO 8601-1:2019 profile, you can use the serializer's native parsing logic. You can also implement a fallback mechanism. The following example shows that, after failing to parse a System.DateTime text representation using System.Text.Json.Utf8JsonReader.TryGetDateTime(System.DateTime@), the converter successfully parses the data using System.DateTime.Parse(System.String):

    using System.Diagnostics;
    using System.Text.Json;
    using System.Text.Json.Serialization;
    using System.Text.RegularExpressions;

    namespace DateTimeConverterExamples;

    public class DateTimeConverterUsingDateTimeParseAsFallback : JsonConverter<DateTime>
    {
        public override DateTime Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            Debug.Assert(typeToConvert == typeof(DateTime));

            if (!reader.TryGetDateTime(out DateTime value))
            {
                value = DateTime.Parse(reader.GetString()!);
            }

            return value;
        }

        public override void Write(Utf8JsonWriter writer, DateTime value, JsonSerializerOptions options)
        {
            writer.WriteStringValue(value.ToString("dd/MM/yyyy"));
        }
    }

    class Program
    {
        private static void ParseDateTimeWithDefaultOptions()
        {
            DateTime _ = JsonSerializer.Deserialize<DateTime>(@"""2019-07-16 16:45:27.4937872+00:00""");
        }

        private static void ProcessDateTimeWithCustomConverter()
        {
            JsonSerializerOptions options = new JsonSerializerOptions();
            options.Converters.Add(new DateTimeConverterUsingDateTimeParseAsFallback());

            string testDateTimeStr = "2019-07-16 16:45:27.4937872+00:00";
            string testDateTimeJson = @"""" + testDateTimeStr + @"""";

            DateTime resultDateTime = JsonSerializer.Deserialize<DateTime>(testDateTimeJson, options);
            Console.WriteLine(resultDateTime);

            string resultDateTimeJson = JsonSerializer.Serialize(DateTime.Parse(testDateTimeStr), options);
            Console.WriteLine(Regex.Unescape(resultDateTimeJson));
        }

        static void Main(string[] args)
        {
            // Parsing non-compliant format as DateTime fails by default.
            try
            {
                ParseDateTimeWithDefaultOptions();
            }
            catch (JsonException e)
            {
                Console.WriteLine(e.Message);
            }

            // Using converters gives you control over the serializers parsing and formatting.
            ProcessDateTimeWithCustomConverter();
        }
    }

    // The example displays output similar to the following:
    // The JSON value could not be converted to System.DateTime.Path: $ | LineNumber: 0 | BytePositionInLine: 35.
    // 7/16/2019 4:45:27 PM
    // "16/07/2019"

Use Unix epoch date format

The following converters handle Unix epoch format with or without a time zone offset (values such as /Date(1590863400000-0700)/ or /Date(1590863400000)/):

    sealed class UnixEpochDateTimeOffsetConverter : System.Text.Json.Serialization.JsonConverter<DateTimeOffset>
    {
        static readonly DateTimeOffset s_epoch = new(1970, 1, 1, 0, 0, 0, TimeSpan.Zero);
        static readonly Regex s_regex = new(
            "^/Date\\(([+-]*\\d+)([+-])(\\d{2})(\\d{2})\\)/$",
            RegexOptions.CultureInvariant);

        public override DateTimeOffset Read(
            ref Utf8JsonReader reader,
            Type typeToConvert,
            JsonSerializerOptions options)
        {
            string formatted = reader.GetString()!;
            Match match = s_regex.Match(formatted);

            if (
                    !match.Success
                    || !long.TryParse(match.Groups[1].Value, NumberStyles.Integer, CultureInfo.InvariantCulture, out long unixTime)
                    || !int.TryParse(match.Groups[3].Value, NumberStyles.Integer, CultureInfo.InvariantCulture, out int hours)
                    || !int.TryParse(match.Groups[4].Value, NumberStyles.Integer, CultureInfo.InvariantCulture, out int minutes))
            {
                throw new System.Text.Json.JsonException();
            }

            int sign = match.Groups[2].Value[0] == '+' ? 1 : -1;
            TimeSpan utcOffset = new(hours * sign, minutes * sign, 0);

            return s_epoch.AddMilliseconds(unixTime).ToOffset(utcOffset);
        }

        public override void Write(
            Utf8JsonWriter writer,
            DateTimeOffset value,
            JsonSerializerOptions options)
        {
            long unixTime = value.ToUnixTimeMilliseconds();

            TimeSpan utcOffset = value.Offset;

            string formatted = string.Create(
                CultureInfo.InvariantCulture,
                $"/Date({unixTime}{(utcOffset >= TimeSpan.Zero ? "+" : "-")}{utcOffset:hhmm})/");

            writer.WriteStringValue(formatted);
        }
    }

    sealed class UnixEpochDateTimeConverter : System.Text.Json.Serialization.JsonConverter<DateTime>
    {
        static readonly DateTime s_epoch = new(1970, 1, 1, 0, 0, 0);
        static readonly Regex s_regex = new(
            "^/Date\\(([+-]*\\d+)\\)/$",
            RegexOptions.CultureInvariant);

        public override DateTime Read(
            ref Utf8JsonReader reader,
            Type typeToConvert,
            JsonSerializerOptions options)
        {
            string formatted = reader.GetString()!;
            Match match = s_regex.Match(formatted);

            if (
                !match.Success
                || !long.TryParse(match.Groups[1].Value, NumberStyles.Integer, CultureInfo.InvariantCulture, out long unixTime))
            {
                throw new System.Text.Json.JsonException();
            }

            return s_epoch.AddMilliseconds(unixTime);
        }

        public override void Write(
            Utf8JsonWriter writer,
            DateTime value,
            JsonSerializerOptions options)
        {
            long unixTime = (value - s_epoch).Ticks / TimeSpan.TicksPerMillisecond;

            string formatted = string.Create(CultureInfo.InvariantCulture, $"/Date({unixTime})/");
            writer.WriteStringValue(formatted);
        }
    }

When using System.Text.Json.Utf8JsonWriter

If you want to write a custom System.DateTime or System.DateTimeOffset text representation with System.Text.Json.Utf8JsonWriter, you can format your custom representation to a System.String, ReadOnlySpan<Byte>, ReadOnlySpan<Char>, or System.Text.Json.JsonEncodedText, then pass it to the corresponding System.Text.Json.Utf8JsonWriter.WriteStringValue*?displayProperty=nameWithType or System.Text.Json.Utf8JsonWriter.WriteString*?displayProperty=nameWithType method.

The following example shows how a custom System.DateTime format can be created with System.DateTime.ToString(System.String,System.IFormatProvider) and then written with the System.Text.Json.Utf8JsonWriter.WriteStringValue(System.String) method:

    using System.Globalization;
    using System.Text;
    using System.Text.Json;

    public class Example
    {
        public static void Main(string[] args)
        {
            var options = new JsonWriterOptions
            {
                Indented = true
            };

            using (var stream = new MemoryStream())
            {
                using (var writer = new Utf8JsonWriter(stream, options))
                {
                    string dateStr = DateTime.UtcNow.ToString("F", CultureInfo.InvariantCulture);

                    writer.WriteStartObject();
                    writer.WriteString("date", dateStr);
                    writer.WriteNumber("temp", 42);
                    writer.WriteEndObject();
                }

                string json = Encoding.UTF8.GetString(stream.ToArray());
                Console.WriteLine(json);
            }
        }
    }

    // The example displays output similar to the following:
    // {
    //     "date": "Tuesday, 27 August 2019 19:21:44",
    //     "temp": 42
    // }

When using System.Text.Json.Utf8JsonReader

If you want to read a custom System.DateTime or System.DateTimeOffset text representation with System.Text.Json.Utf8JsonReader, you can get the value of the current JSON token as a System.String using the System.Text.Json.Utf8JsonReader.GetString method, then parse the value using custom logic.

The following example shows how a custom System.DateTimeOffset text representation can be retrieved using the System.Text.Json.Utf8JsonReader.GetString method, then parsed using System.DateTimeOffset.ParseExact(System.String,System.String,System.IFormatProvider):

    using System.Globalization;
    using System.Text;
    using System.Text.Json;

    public class Example
    {
        public static void Main(string[] args)
        {
            byte[] utf8Data = Encoding.UTF8.GetBytes(@"""Friday, 26 July 2019 00:00:00""");

            var json = new Utf8JsonReader(utf8Data);
            while (json.Read())
            {
                if (json.TokenType == JsonTokenType.String)
                {
                    string value = json.GetString();
                    DateTimeOffset dto = DateTimeOffset.ParseExact(value, "F", CultureInfo.InvariantCulture);
                    Console.WriteLine(dto);
                }
            }
        }
    }

    // The example displays output similar to the following:
    // 7/26/2019 12:00:00 AM -04:00

The extended ISO 8601-1:2019 profile in System.Text.Json

Date and time components

The extended ISO 8601-1:2019 profile implemented in System.Text.Json?displayProperty=fullName defines the following components for date and time representations. These components are used to define various supported levels of granularity when parsing and formatting System.DateTime and System.DateTimeOffset representations.

 Component   Format   Description

 Year   "yyyy"   0001-9999

 Month   "MM"   01-12

 Day   "dd"   01-28, 01-29, 01-30, 01-31 based on month/year.

 Hour   "HH"   00-23

 Minute   "mm"   00-59

 Second   "ss"   00-59

 Second fraction   "FFFFFFF"   Minimum of one digit, maximum of 16 digits.

 Time offset   "K"   Either "Z" or "('+'/'-')HH':'mm".

 Partial time   "HH':'mm':'ss[FFFFFFF]"   Time without UTC offset information.

 Full date   "yyyy'-'MM'-'dd"   Calendar date.

 Full time   "'Partial time'K"   UTC of day or Local time of day with the time offset between local time and UTC.

 Date time   "'Full date''T''Full time'"   Calendar date and time of day, for example, 2019-07-26T16:59:57-05:00.

Support for parsing

The following levels of granularity are defined for parsing:

• 'Full date'

• "yyyy'-'MM'-'dd"

• "'Full date''T''Hour'':''Minute'"

• "yyyy'-'MM'-'dd'T'HH':'mm"

• "'Full date''T''Partial time'"

• "yyyy'-'MM'-'dd'T'HH':'mm':'ss" (The Sortable ("s") Format Specifier)

• "yyyy'-'MM'-'dd'T'HH':'mm':'ss'.'FFFFFFF"

• "'Full date''T''Time hour'':''Minute''Time offset'"

• "yyyy'-'MM'-'dd'T'HH':'mmZ"

• "yyyy'-'MM'-'dd'T'HH':'mm('+'/'-')HH':'mm"

• 'Date time'

• "yyyy'-'MM'-'dd'T'HH':'mm':'ssZ"

• "yyyy'-'MM'-'dd'T'HH':'mm':'ss'.'FFFFFFFZ"

• "yyyy'-'MM'-'dd'T'HH':'mm':'ss('+'/'-')HH':'mm"

• "yyyy'-'MM'-'dd'T'HH':'mm':'ss'.'FFFFFFF('+'/'-')HH':'mm"

This level of granularity is compliant with RFC 3339, a widely adopted profile of ISO 8601 used for interchanging date and time information. However, there are a few restrictions in the System.Text.Json implementation.

• RFC 3339 doesn't specify a maximum number of fractional-second digits, but specifies that at least one digit must follow the period, if a fractional-second section is present. The implementation in System.Text.Json allows up to 16 digits (to support interop with other programming languages and frameworks), but parses only the first seven. A System.Text.Json.JsonException will be thrown if there are more than 16 fractional second digits when reading DateTime and DateTimeOffset instances.

• RFC 3339 allows the "T" and "Z" characters to be "t" or "z" respectively, but allows applications to limit support to just the upper-case variants. The implementation in System.Text.Json requires them to be "T" and "Z". A System.Text.Json.JsonException will be thrown if input payloads contain "t" or "z" when reading DateTime and DateTimeOffset instances.

• RFC 3339 specifies that the date and time sections are separated by "T", but allows applications to separate them by a space (" ") instead. System.Text.Json requires date and time sections to be separated with "T". A System.Text.Json.JsonException will be thrown if input payloads contain a space (" ") when reading DateTime and DateTimeOffset instances.

If there are decimal fractions for seconds, there must be at least one digit. 2019-07-26T00:00:00. isn't allowed. While up to 16 fractional digits are allowed, only the first seven are parsed. Anything beyond that is considered a zero. For example, 2019-07-26T00:00:00.1234567890 will be parsed as if it's 2019-07-26T00:00:00.1234567. This approach maintains compatibility with the System.DateTime implementation, which is limited to this resolution.

Leap seconds aren't supported.

Support for formatting

The following levels of granularity are defined for formatting:

• "'Full date''T''Partial time'"

• "yyyy'-'MM'-'dd'T'HH':'mm':'ss" (The Sortable ("s") Format Specifier)

Used to format a System.DateTime without fractional seconds and without offset information.

• "yyyy'-'MM'-'dd'T'HH':'mm':'ss'.'FFFFFFF"

Used to format a System.DateTime with fractional seconds but without offset information.

• 'Date time'

• "yyyy'-'MM'-'dd'T'HH':'mm':'ssZ"

Used to format a System.DateTime without fractional seconds but with a UTC offset.

• "yyyy'-'MM'-'dd'T'HH':'mm':'ss'.'FFFFFFFZ"

Used to format a System.DateTime with fractional seconds and with a UTC offset.

• "yyyy'-'MM'-'dd'T'HH':'mm':'ss('+'/'-')HH':'mm"

Used to format a System.DateTime or System.DateTimeOffset without fractional seconds but with a local offset.

• "yyyy'-'MM'-'dd'T'HH':'mm':'ss'.'FFFFFFF('+'/'-')HH':'mm"

Used to format a System.DateTime or System.DateTimeOffset with fractional seconds and with a local offset.

This level of granularity is compliant with RFC 3339.

If the round-trip format representation of a System.DateTime or System.DateTimeOffset instance has trailing zeros in its fractional seconds, then System.Text.Json.JsonSerializer and System.Text.Json.Utf8JsonWriter will format a representation of the instance without trailing zeros. For example, a System.DateTime instance whose round-trip format representation is 2019-04-24T14:50:17.1010000Z, will be formatted as 2019-04-24T14:50:17.101Z by System.Text.Json.JsonSerializer and System.Text.Json.Utf8JsonWriter.

If the round-trip format representation of a System.DateTime or System.DateTimeOffset instance has all zeros in its fractional seconds, then System.Text.Json.JsonSerializer and System.Text.Json.Utf8JsonWriter will format a representation of the instance without fractional seconds. For example, a System.DateTime instance whose round-trip format representation is 2019-04-24T14:50:17.0000000+02:00, will be formatted as 2019-04-24T14:50:17+02:00 by System.Text.Json.JsonSerializer and System.Text.Json.Utf8JsonWriter.

Truncating zeros in fractional-second digits allows the smallest output needed to preserve information on a round trip to be written.

A maximum of seven fractional-second digits are written. This maximum aligns with the System.DateTime implementation, which is limited to this resolution.

How to: Use time zones in date and time arithmetic

Ordinarily, when you perform date and time arithmetic using System.DateTime or System.DateTimeOffset values, the result does not reflect any time zone adjustment rules. This is true even when the time zone of the date and time value is clearly identifiable (for example, when the System.DateTime.Kind property is set to System.DateTimeKind.Local). This topic shows how to perform arithmetic operations on date and time values that belong to a particular time zone. The results of the arithmetic operations will reflect the time zone's adjustment rules.

To apply adjustment rules to date and time arithmetic

• Implement some method of closely coupling a date and time value with the time zone to which it belongs. For example, declare a structure that includes both the date and time value and its time zone. The following example uses this approach to link a System.DateTime value with its time zone.

    // Define a structure for DateTime values for internal use only
    internal struct TimeWithTimeZone
    {
        TimeZoneInfo TimeZone;
        DateTime Time;
    }

    ' Define a structure for DateTime values for internal use only
    Friend Structure TimeWithTimeZone
        Dim TimeZone As TimeZoneInfo
        Dim Time As Date
    End Structure

• Convert a time to Coordinated Universal Time (UTC) by calling either the System.TimeZoneInfo.ConvertTimeToUtc* method or the System.TimeZoneInfo.ConvertTime* method.

• Perform the arithmetic operation on the UTC time.

• Convert the time from UTC to the original time's associated time zone by calling the System.TimeZoneInfo.ConvertTime%28System.DateTime%2CSystem.TimeZoneInfo%29?displayProperty=nameWithType method.

Example

The following example adds two hours and thirty minutes to March 9, 2008, at 1:30 A.M. Central Standard Time. The time zone's transition to daylight saving time occurs thirty minutes later, at 2:00 A.M. on March 9, 2008. Because the example follows the four steps listed in the previous section, it correctly reports the resulting time as 5:00 A.M. on March 9, 2008.

    using System;

    public struct TimeZoneTime
    {
        public TimeZoneInfo TimeZone;
        public DateTime Time;

        public TimeZoneTime(TimeZoneInfo tz, DateTime time)
        {
            ArgumentNullException.ThrowIfNull(tz);

            TimeZone = tz;
            Time = time;
        }

        public TimeZoneTime AddTime(TimeSpan interval)
        {
            // Convert time to UTC
            DateTime utcTime = TimeZoneInfo.ConvertTimeToUtc(Time, TimeZone);
            // Add time interval to time
            utcTime = utcTime.Add(interval);
            // Convert time back to time in time zone
            return new TimeZoneTime(TimeZone, TimeZoneInfo.ConvertTime(utcTime,
                                    TimeZoneInfo.Utc, TimeZone));
        }
    }

    public class TimeArithmetic
    {
        public const string TzName = "Central Standard Time";

        public static void Main()
        {
            try
            {
                TimeZoneTime cstTime1, cstTime2;

                TimeZoneInfo cst = TimeZoneInfo.FindSystemTimeZoneById(TzName);
                DateTime time1 = new(2008, 3, 9, 1, 30, 0);
                TimeSpan twoAndAHalfHours = new(2, 30, 0);

                cstTime1 = new TimeZoneTime(cst, time1);
                cstTime2 = cstTime1.AddTime(twoAndAHalfHours);
                Console.WriteLine($"{cstTime1.Time} + {twoAndAHalfHours.ToString()} hours = {cstTime2.Time}");
            }
            catch
            {
                Console.WriteLine($"Unable to find {TzName}.");
            }
        }
    }

    Public Structure TimeZoneTime
        Public TimeZone As TimeZoneInfo
        Public Time As Date

        Public Sub New(tz As TimeZoneInfo, time As Date)
            If tz Is Nothing Then _
               Throw New ArgumentNullException("The time zone cannot be a null reference.")

            Me.TimeZone = tz
            Me.Time = time
        End Sub

        Public Function AddTime(interval As TimeSpan) As TimeZoneTime
            ' Convert time to UTC
            Dim utcTime As DateTime = TimeZoneInfo.ConvertTimeToUtc(Me.Time, _
                                                                    Me.TimeZone)
            ' Add time interval to time
            utcTime = utcTime.Add(interval)
            ' Convert time back to time in time zone
            Return New TimeZoneTime(Me.TimeZone, TimeZoneInfo.ConvertTime(utcTime, _
                                    TimeZoneInfo.Utc, Me.TimeZone))
        End Function
    End Structure

    Module TimeArithmetic
        Public Const tzName As String = "Central Standard Time"

        Public Sub Main()
            Try
                Dim cstTime1, cstTime2 As TimeZoneTime

                Dim cst As TimeZoneInfo = TimeZoneInfo.FindSystemTimeZoneById(tzName)
                Dim time1 As Date = #03/09/2008 1:30AM#
                Dim twoAndAHalfHours As New TimeSpan(2, 30, 0)

                cstTime1 = New TimeZoneTime(cst, time1)
                cstTime2 = cstTime1.AddTime(twoAndAHalfHours)

                Console.WriteLine("{0} + {1} hours = {2}", cstTime1.Time, _
                                                           twoAndAHalfHours.ToString(), _
                                                           cstTime2.Time)
            Catch
                Console.WriteLine("Unable to find {0}.", tzName)
            End Try
        End Sub
    End Module

Both System.DateTime and System.DateTimeOffset values are disassociated from any time zone to which they might belong. To perform date and time arithmetic in a way that automatically applies a time zone's adjustment rules, the time zone to which any date and time value belongs must be immediately identifiable. This means that a date and time and its associated time zone must be tightly coupled. There are several ways to do this, which include the following:

• Assume that all times used in an application belong to a particular time zone. Although appropriate in some cases, this approach offers limited flexibility and possibly limited portability.

• Define a type that tightly couples a date and time with its associated time zone by including both as fields of the type. This approach is used in the code example, which defines a structure to store the date and time and the time zone in two member fields.

The example illustrates how to perform arithmetic operations on System.DateTime values so that time zone adjustment rules are applied to the result. However, System.DateTimeOffset values can be used just as easily. The following example illustrates how the code in the original example might be adapted to use System.DateTimeOffset instead of System.DateTime values.

    using System;

    public struct TimeZoneTime2
    {
        public TimeZoneInfo TimeZone;
        public DateTimeOffset Time;

        public TimeZoneTime2(TimeZoneInfo tz, DateTimeOffset time)
        {
            ArgumentNullException.ThrowIfNull(tz);

            TimeZone = tz;
            Time = time;
        }

        public TimeZoneTime2 AddTime(TimeSpan interval)
        {
            // Convert time to UTC
            DateTimeOffset utcTime = TimeZoneInfo.ConvertTime(Time, TimeZoneInfo.Utc);
            // Add time interval to time
            utcTime = utcTime.Add(interval);
            // Convert time back to time in time zone
            return new TimeZoneTime2(TimeZone, TimeZoneInfo.ConvertTime(utcTime, TimeZone));
        }
    }

    public class TimeArithmetic2
    {
        public const string tzName = "Central Standard Time";

        public static void Main()
        {
            try
            {
                TimeZoneTime2 cstTime1, cstTime2;

                TimeZoneInfo cst = TimeZoneInfo.FindSystemTimeZoneById(tzName);
                DateTime time1 = new(2008, 3, 9, 1, 30, 0);
                TimeSpan twoAndAHalfHours = new(2, 30, 0);

                cstTime1 = new TimeZoneTime2(cst,
                               new DateTimeOffset(time1, cst.GetUtcOffset(time1)));
                cstTime2 = cstTime1.AddTime(twoAndAHalfHours);
                Console.WriteLine($"{cstTime1.Time} + {twoAndAHalfHours.ToString()} hours = {cstTime2.Time}");
            }
            catch
            {
                Console.WriteLine($"Unable to find {tzName}.");
            }
        }
    }

