• Implement the notification logic by calling observers' [System.IObserver1.OnNext*?displayProperty=nameWithType](xref:System.IObserver1.OnNext*?displayProperty=nameWithType), [System.IObserver1.OnError*?displayProperty=nameWithType](xref:System.IObserver1.OnError*?displayProperty=nameWithType), and [System.IObserver1.OnCompleted*?displayProperty=nameWithType](xref:System.IObserver1.OnCompleted*?displayProperty=nameWithType) methods.

In some cases, a provider might not call [System.IObserver1.OnError*](xref:System.IObserver1.OnError*) when an error occurs. The following GetTemperature method simulates a monitor that reads temperature data every five seconds and notifies observers if the temperature has changed by at least .1 degree since the previous reading. If the device doesn't report a temperature (that is, if its value is null), the provider notifies observers that the transmission is complete by calling each observer's [System.IObserver1.OnCompleted*](xref:System.IObserver1.OnCompleted*) method and clears the [System.Collections.Generic.List1](xref:System.Collections.Generic.List1) collection. In this example, the provider never calls [System.IObserver1.OnError*](xref:System.IObserver1.OnError*).

    public async Task GetTemperatureAsync(CancellationToken cancellationToken = default)
    {
        // Sample data that mimics a temperature device. A null value signals the end of transmission.
        decimal?[] temps =
        [
            14.6m, 14.65m, 14.7m, 14.9m, 14.9m, 15.2m,
            15.25m, 15.2m, 15.4m, 15.45m, null
        ];

        decimal? previous = null;

        foreach (decimal? temp in temps)
        {
            await Task.Delay(TimeSpan.FromSeconds(2.5), cancellationToken);

            if (temp is decimal value)
            {
                // Notify only after at least a 0.1° change.
                if (previous is null || Math.Abs(value - previous.Value) >= 0.1m)
                {
                    NotifyAll(new Temperature(value, DateTime.Now));
                    previous = value;
                }
            }
            else
            {
                CompleteAll();
                break;
            }
        }
    }

    private void NotifyAll(Temperature data)
    {
        IObserver<Temperature>[] snapshot;
        lock (_sync)
        {
            snapshot = [.. _observers];
        }

        foreach (IObserver<Temperature> observer in snapshot)
            observer.OnNext(data);
    }

    private void CompleteAll()
    {
        IObserver<Temperature>[] snapshot;
        lock (_sync)
        {
            snapshot = [.. _observers];
            _observers.Clear();
        }

        foreach (IObserver<Temperature> observer in snapshot)
            observer.OnCompleted();
    }

