                For Each observer In snapshot
                    observer.OnNext(data)
                Next
            End Sub

            Private Sub CompleteAll()
                Dim snapshot As IObserver(Of Temperature)()
                SyncLock _sync
                    snapshot = _observers.ToArray()
                    _observers.Clear()
                End SyncLock

                For Each observer In snapshot
                    observer.OnCompleted()
                Next
            End Sub
            ' </Notify>
        End Class

    End Namespace

