The following example uses the System.IO.DirectoryInfo.EnumerateFiles*?displayProperty=nameWithType method to list all files whose System.IO.FileInfo.Length exceeds 10MB. This example first enumerates the top-level directories, to catch possible unauthorized access exceptions, and then enumerates the files.

    using System;
    using System.IO;

    class Program
    {
        static void Main(string[] args)
        {
            // Set a variable to the My Documents path.
            string docPath = Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments);

            DirectoryInfo diTop = new DirectoryInfo(docPath);

            try
            {
                foreach (var fi in diTop.EnumerateFiles())
                {
                    try
                    {
                        // Display each file over 10 MB;
                        if (fi.Length > 10000000)
                        {
                            Console.WriteLine($"{fi.FullName}\t\t{fi.Length.ToString("N0")}");
                        }
                    }
                    catch (UnauthorizedAccessException unAuthTop)
                    {
                        Console.WriteLine($"{unAuthTop.Message}");
                    }
                }

                foreach (var di in diTop.EnumerateDirectories("*"))
                {
                    try
                    {
                        foreach (var fi in di.EnumerateFiles("*", SearchOption.AllDirectories))
                        {
                            try
                            {
                                // Display each file over 10 MB;
                                if (fi.Length > 10000000)
                                {
                                    Console.WriteLine($"{fi.FullName}\t\t{fi.Length.ToString("N0")}");
                                }
                            }
                            catch (UnauthorizedAccessException unAuthFile)
                            {
                                Console.WriteLine($"unAuthFile: {unAuthFile.Message}");
                            }
                        }
                    }
                    catch (UnauthorizedAccessException unAuthSubDir)
                    {
                        Console.WriteLine($"unAuthSubDir: {unAuthSubDir.Message}");
                    }
                }
            }
            catch (DirectoryNotFoundException dirNotFound)
            {
                Console.WriteLine($"{dirNotFound.Message}");
            }
            catch (UnauthorizedAccessException unAuthDir)
            {
                Console.WriteLine($"unAuthDir: {unAuthDir.Message}");
            }
            catch (PathTooLongException longPath)
            {
                Console.WriteLine($"{longPath.Message}");
            }
        }
    }

