How to serialize using XmlSerializer (LINQ to XML)

This article shows an example that serializes and deserializes using System.Xml.Serialization.XmlSerializer in C# and Visual Basic.

Example: Create objects that contain XElement objects, then serialize and deserialize them

The following example creates a number of objects that contain System.Xml.Linq.XElement objects. It then serializes them to a memory stream, and then deserializes them from the memory stream.

    using System;
    using System.IO;
    using System.Linq;
    using System.Xml;
    using System.Xml.Serialization;
    using System.Xml.Linq;

    public class XElementContainer
    {
        public XElement member;

        public XElementContainer()
        {
            member = XLinqTest.CreateXElement();
        }

        public override string ToString()
        {
            return member.ToString();
        }
    }

    public class XElementNullContainer
    {
        public XElement member;

        public XElementNullContainer()
        {
        }
    }

    class XLinqTest
    {
        static void Main(string[] args)
        {
            Test<XElementNullContainer>(new XElementNullContainer());
            Test<XElement>(CreateXElement());
            Test<XElementContainer>(new XElementContainer());
        }

        public static XElement CreateXElement()
        {
            XNamespace ns = "http://www.adventure-works.com";
            return new XElement(ns + "aw");
        }

        static void Test<T>(T obj)
        {
            using (MemoryStream stream = new MemoryStream())
            {
                XmlSerializer s = new XmlSerializer(typeof(T));
                Console.WriteLine("Testing for type: {0}", typeof(T));
                s.Serialize(XmlWriter.Create(stream), obj);
                stream.Flush();
                stream.Seek(0, SeekOrigin.Begin);
                object o = s.Deserialize(XmlReader.Create(stream));
                Console.WriteLine("  Deserialized type: {0}", o.GetType());
            }
        }
    }

