          if (ln.OpeningBalance == 0.00) ln.ComputeOpeningBalance();
          if (ln.Rate == 0.00) ln.ComputeRate();
          if (ln.Term == 0) ln.ComputeTerm();
          if (ln.Payment == 0.00) ln.ComputePayment();

