 System.SByte?displayProperty=nameWithType   ELEMENT_TYPE_I1

 System.Byte?displayProperty=nameWithType   ELEMENT_TYPE_UI1

 System.Char?displayProperty=nameWithType   ELEMENT_TYPE_CHAR

 System.Int16?displayProperty=nameWithType   ELEMENT_TYPE_I2

 System.UInt16?displayProperty=nameWithType   ELEMENT_TYPE_U2

 System.Int32?displayProperty=nameWithType   ELEMENT_TYPE_I4

 System.UInt32?displayProperty=nameWithType   ELEMENT_TYPE_U4

 System.Int64?displayProperty=nameWithType   ELEMENT_TYPE_I8

 System.UInt64?displayProperty=nameWithType   ELEMENT_TYPE_U8

 System.Single?displayProperty=nameWithType   ELEMENT_TYPE_R4

 System.Double?displayProperty=nameWithType   ELEMENT_TYPE_R8

