You can also prevent a continuation from executing if its antecedent is canceled without providing the continuation a cancellation token. Provide the token by specifying the System.Threading.Tasks.TaskContinuationOptions.NotOnCanceled?displayProperty=nameWithType option when you create the continuation, as shown in the following example:

    using System;
    using System.Threading;
    using System.Threading.Tasks;

    public class CancellationTwoExample
    {
        public static async Task Main()
        {
            using var cts = new CancellationTokenSource();
            CancellationToken token = cts.Token;
            cts.Cancel();

            var task = Task.FromCanceled(token);
            Task continuation =
                task.ContinueWith(
                    antecedent => Console.WriteLine("The continuation is running."),
                    TaskContinuationOptions.NotOnCanceled);

            try
            {
                await task;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"{ex.GetType().Name}: {ex.Message}");
                Console.WriteLine();
            }

            Console.WriteLine($"Task {task.Id}: {task.Status:G}");
            Console.WriteLine($"Task {continuation.Id}: {continuation.Status:G}");
        }
    }
    // The example displays the similar output:
    //       TaskCanceledException: A task was canceled.
    //
    //       Task 1: Canceled
    //       Task 2: Canceled

    Imports System.Threading
    Imports System.Threading.Tasks

    Module Example
        Public Sub Main()
            Dim cts As New CancellationTokenSource()
            Dim token As CancellationToken = cts.Token
            cts.Cancel()

            Dim t As Task = Task.FromCanceled(token)
            Dim continuation As Task = t.ContinueWith(Sub(antecedent)
                                                          Console.WriteLine("The continuation is running.")
                                                      End Sub, TaskContinuationOptions.NotOnCanceled)
            Try
                t.Wait()
            Catch e As AggregateException
                For Each ie In e.InnerExceptions
                    Console.WriteLine("{0}: {1}", ie.GetType().Name, ie.Message)
                Next
                Console.WriteLine()
            Finally
                cts.Dispose()
            End Try

            Console.WriteLine("Task {0}: {1:G}", t.Id, t.Status)
            Console.WriteLine("Task {0}: {1:G}", continuation.Id,
                              continuation.Status)
        End Sub
    End Module
    ' The example displays the following output:
    '       TaskCanceledException: A task was canceled.
    '
    '       Task 1: Canceled
    '       Task 2: Canceled

After a continuation goes into the System.Threading.Tasks.TaskStatus.Canceled state, it might affect continuations that follow, depending on the System.Threading.Tasks.TaskContinuationOptions that were specified for those continuations.

Continuations that are disposed won't start.

Continuations and child tasks

A continuation doesn't run until the antecedent and all of its attached child tasks have completed. A continuation doesn't wait for detached child tasks to finish. The following two examples illustrate child tasks that are attached to and detached from an antecedent that creates a continuation. In the following example, the continuation runs only after all child tasks have completed, and multiple runs of the example produces identical output each time. The example launches the antecedent by calling the System.Threading.Tasks.TaskFactory.StartNew*?displayProperty=nameWithType method because by default the System.Threading.Tasks.Task.Run*?displayProperty=nameWithType method creates a parent task whose default task creation option is System.Threading.Tasks.TaskCreationOptions.DenyChildAttach?displayProperty=nameWithType.

    using System;
    using System.Threading.Tasks;

    public class AttachedExample
    {
        public static async Task Main()
        {
            await Task.Factory
                      .StartNew(
                () =>
                {
                    Console.WriteLine($"Running antecedent task {Task.CurrentId}...");
                    Console.WriteLine("Launching attached child tasks...");
                    for (int ctr = 1; ctr <= 5; ctr++)
                    {
                        int index = ctr;
                        Task.Factory.StartNew(async value =>
                        {
                            Console.WriteLine($"   Attached child task #{value} running");
                            await Task.Delay(1000);
                        }, index, TaskCreationOptions.AttachedToParent);
                    }
                    Console.WriteLine("Finished launching attached child tasks...");
                }).ContinueWith(
                    antecedent =>
                        Console.WriteLine($"Executing continuation of Task {antecedent.Id}"));
        }
    }
    // The example displays the similar output:
    //     Running antecedent task 1...
    //     Launching attached child tasks...
    //     Finished launching attached child tasks...
    //        Attached child task #1 running
    //        Attached child task #5 running
    //        Attached child task #3 running
    //        Attached child task #2 running
    //        Attached child task #4 running
    //     Executing continuation of Task 1

    Imports System.Threading
    Imports System.Threading.Tasks

    Public Module Example
        Public Sub Main()
            Dim t = Task.Factory.StartNew(Sub()
                                              Console.WriteLine("Running antecedent task {0}...",
                                                                Task.CurrentId)
                                              Console.WriteLine("Launching attached child tasks...")
                                              For ctr As Integer = 1 To 5
                                                  Dim index As Integer = ctr
                                                  Task.Factory.StartNew(Sub(value)
                                                                            Console.WriteLine("   Attached child task #{0} running",
                                                                                              value)
                                                                            Thread.Sleep(1000)
                                                                        End Sub, index, TaskCreationOptions.AttachedToParent)
                                              Next
                                              Console.WriteLine("Finished launching attached child tasks...")
                                          End Sub)
            Dim continuation = t.ContinueWith(Sub(antecedent)
                                                  Console.WriteLine("Executing continuation of Task {0}",
                                                                    antecedent.Id)
                                              End Sub)
            continuation.Wait()
        End Sub
    End Module
    ' The example displays the following output:
    '       Running antecedent task 1...
    '       Launching attached child tasks...
    '       Finished launching attached child tasks...
    '          Attached child task #5 running
    '          Attached child task #1 running
    '          Attached child task #2 running
    '          Attached child task #3 running
    '          Attached child task #4 running
    '       Executing continuation of Task 1

If child tasks are detached from the antecedent, however, the continuation runs as soon as the antecedent has terminated, regardless of the state of the child tasks. As a result, multiple runs of the following example can produce variable output that depends on how the task scheduler handled each child task:

    using System;
    using System.Threading.Tasks;

    public class DetachedExample
    {
        public static async Task Main()
        {
            Task task =
                Task.Factory.StartNew(
                    () =>
                    {
                        Console.WriteLine($"Running antecedent task {Task.CurrentId}...");
                        Console.WriteLine("Launching attached child tasks...");
                        for (int ctr = 1; ctr <= 5; ctr++)
                        {
                            int index = ctr;
                            Task.Factory.StartNew(
                                async value =>
                                {
                                    Console.WriteLine($"   Attached child task #{value} running");
                                    await Task.Delay(1000);
                                }, index);
                        }
                        Console.WriteLine("Finished launching detached child tasks...");
                    }, TaskCreationOptions.DenyChildAttach);

            Task continuation =
                task.ContinueWith(
                    antecedent =>
                        Console.WriteLine($"Executing continuation of Task {antecedent.Id}"));

            await continuation;

            Console.ReadLine();
        }
    }
    // The example displays the similar output:
    //     Running antecedent task 1...
    //     Launching attached child tasks...
    //     Finished launching detached child tasks...
    //     Executing continuation of Task 1
    //        Attached child task #1 running
    //        Attached child task #5 running
    //        Attached child task #2 running
    //        Attached child task #3 running
    //        Attached child task #4 running

    Imports System.Threading
    Imports System.Threading.Tasks

