                                                  Dim index As Integer = ctr
                                                  Task.Factory.StartNew(Sub(value)
                                                                            Console.WriteLine("   Attached child task #{0} running",
                                                                                              value)
                                                                            Thread.Sleep(1000)
                                                                        End Sub, index)
