Create pre-computed tasks

In this article, you'll learn how to use the System.Threading.Tasks.Task.FromResult*?displayProperty=nameWithType method to retrieve the results of asynchronous download operations that are held in a cache. The System.Threading.Tasks.Task.FromResult* method returns a finished [System.Threading.Tasks.Task1](xref:System.Threading.Tasks.Task1) object that holds the provided value as its [System.Threading.Tasks.Task1.Result](xref:System.Threading.Tasks.Task1.Result) property. This method is useful when you perform an asynchronous operation that returns a [System.Threading.Tasks.Task1](xref:System.Threading.Tasks.Task1) object, and the result of that [System.Threading.Tasks.Task1](xref:System.Threading.Tasks.Task1) object is already computed.

Example

The following example downloads strings from the web. It defines the DownloadStringAsync method. This method downloads strings from the web asynchronously. This example also uses a [System.Collections.Concurrent.ConcurrentDictionary2](xref:System.Collections.Concurrent.ConcurrentDictionary2) object to cache the results of previous operations. If the input address is held in this cache, DownloadStringAsync uses the System.Threading.Tasks.Task.FromResult* method to produce a [System.Threading.Tasks.Task1](xref:System.Threading.Tasks.Task1) object that holds the content at that address. Otherwise, DownloadStringAsync downloads the file from the web and adds the result to the cache.

    using System;
    using System.Collections.Concurrent;
    using System.Collections.Generic;
    using System.Diagnostics;
    using System.Linq;
    using System.Net.Http;
    using System.Threading.Tasks;

    public static class DownloadCache
    {
        private static readonly ConcurrentDictionary<string, string> s_cachedDownloads = new();
        private static readonly HttpClient s_httpClient = new();

        public static Task<string> DownloadStringAsync(string address)
        {
            if (s_cachedDownloads.TryGetValue(address, out string? content))
            {
                return Task.FromResult(content);
            }

            return Task.Run(async () =>
            {
                content = await s_httpClient.GetStringAsync(address);
                s_cachedDownloads.TryAdd(address, content);

                return content;
            });
        }

        public static async Task Main()
        {
            string[] urls = new[]
            {
                "https://learn.microsoft.com/aspnet/core",
                "https://learn.microsoft.com/dotnet",
                "https://learn.microsoft.com/dotnet/architecture/dapr-for-net-developers",
                "https://learn.microsoft.com/dotnet/azure",
                "https://learn.microsoft.com/dotnet/desktop/wpf",
                "https://learn.microsoft.com/dotnet/devops/create-dotnet-github-action",
                "https://learn.microsoft.com/dotnet/machine-learning",
                "https://learn.microsoft.com/xamarin",
                "https://dotnet.microsoft.com/",
                "https://www.microsoft.com"
            };

            Stopwatch stopwatch = Stopwatch.StartNew();
            IEnumerable<Task<string>> downloads = urls.Select(DownloadStringAsync);

            static void StopAndLogElapsedTime(
                int attemptNumber, Stopwatch stopwatch, Task<string[]> downloadTasks)
            {
                stopwatch.Stop();

                int charCount = downloadTasks.Result.Sum(result => result.Length);
                long elapsedMs = stopwatch.ElapsedMilliseconds;

                Console.WriteLine(
                    $"Attempt number: {attemptNumber}\n" +
                    $"Retrieved characters: {charCount:#,0}\n" +
                    $"Elapsed retrieval time: {elapsedMs:#,0} milliseconds.\n");
            }

            await Task.WhenAll(downloads).ContinueWith(
                downloadTasks => StopAndLogElapsedTime(1, stopwatch, downloadTasks));

            // Perform the same operation a second time. The time required
            // should be shorter because the results are held in the cache.
            stopwatch.Restart();

            downloads = urls.Select(DownloadStringAsync);

            await Task.WhenAll(downloads).ContinueWith(
                downloadTasks => StopAndLogElapsedTime(2, stopwatch, downloadTasks));
        }
        // Sample output:
        //     Attempt number: 1
        //     Retrieved characters: 754,585
        //     Elapsed retrieval time: 2,857 milliseconds.

        //     Attempt number: 2
        //     Retrieved characters: 754,585
        //     Elapsed retrieval time: 1 milliseconds.
    }

    Imports System.Collections.Concurrent
    Imports System.Net.Http

