            'Count of files traversed and timer for diagnostic output
            Dim fileCount As Integer = 0
            Dim sw As Stopwatch = Stopwatch.StartNew()

            ' Determine whether to parallelize file processing on each folder based on processor count.
            Dim procCount As Integer = System.Environment.ProcessorCount

            ' Data structure to hold names of subfolders to be examined for files.
            Dim dirs As New Stack(Of String)

            If Not Directory.Exists(root) Then Throw New ArgumentException(
                "The given root directory doesn't exist.", NameOf(root))

            dirs.Push(root)

            While (dirs.Count > 0)
                Dim currentDir As String = dirs.Pop()
                Dim subDirs() As String = Nothing
                Dim files() As String = Nothing

                Try
                    subDirs = Directory.GetDirectories(currentDir)
                    ' Thrown if we do not have discovery permission on the directory.
                Catch e As UnauthorizedAccessException
                    Console.WriteLine(e.Message)
                    Continue While
                    ' Thrown if another process has deleted the directory after we retrieved its name.
                Catch e As DirectoryNotFoundException
                    Console.WriteLine(e.Message)
                    Continue While
                End Try

                Try
                    files = Directory.GetFiles(currentDir)
                Catch e As UnauthorizedAccessException
                    Console.WriteLine(e.Message)
                    Continue While
                Catch e As DirectoryNotFoundException
                    Console.WriteLine(e.Message)
                    Continue While
                Catch e As IOException
                    Console.WriteLine(e.Message)
                    Continue While
                End Try

                ' Execute in parallel if there are enough files in the directory.
                ' Otherwise, execute sequentially.Files are opened and processed
                ' synchronously but this could be modified to perform async I/O.
                Try
                    If files.Length < procCount Then
                        For Each file In files
                            action(file)
                            fileCount += 1
                        Next
                    Else
                        Parallel.ForEach(files, Function() 0, Function(file, loopState, localCount)
                                                                  action(file)
                                                                  localCount = localCount + 1
                                                                  Return localCount
                                                              End Function,
                                         Sub(c)
                                             Interlocked.Add(fileCount, c)
                                         End Sub)
                    End If
                Catch ae As AggregateException
                    ae.Handle(Function(ex)

                                  If TypeOf (ex) Is UnauthorizedAccessException Then

                                      ' Here we just output a message and go on.
                                      Console.WriteLine(ex.Message)
                                      Return True
                                  End If
                                  ' Handle other exceptions here if necessary...

                                  Return False
                              End Function)
                End Try
                ' Push the subdirectories onto the stack for traversal.
                ' This could also be done before handing the files.
                For Each str As String In subDirs
                    dirs.Push(str)
                Next

                ' For diagnostic purposes.
                Console.WriteLine("Processed {0} files in {1} milliseconds", fileCount, sw.ElapsedMilliseconds)
            End While
        End Sub
    End Module

In this example, the file I/O is performed synchronously. When dealing with large files or slow network connections, it might be preferable to access the files asynchronously. You can combine asynchronous I/O techniques with parallel iteration. For more information, see TPL and Traditional .NET Asynchronous Programming.

The example uses the local fileCount variable to maintain a count of the total number of files processed. Because the variable might be accessed concurrently by multiple tasks, access to it is synchronized by calling the System.Threading.Interlocked.Add*?displayProperty=nameWithType method.

Note that if an exception is thrown on the main thread, the threads that are started by the System.Threading.Tasks.Parallel.ForEach* method might continue to run. To stop these threads, you can set a Boolean variable in your exception handlers, and check its value on each iteration of the parallel loop. If the value indicates that an exception has been thrown, use the System.Threading.Tasks.ParallelLoopState variable to stop or break from the loop. For more information, see How to: Stop or Break from a Parallel.For Loop.

