• Task-based Asynchronous Programming

How to: Return a Value from a Task

This example shows how to use the [System.Threading.Tasks.Task1?displayProperty=nameWithType](xref:System.Threading.Tasks.Task1?displayProperty=nameWithType) class to return a value from the [System.Threading.Tasks.Task1.Result](xref:System.Threading.Tasks.Task1.Result) property. To use this example, you must ensure that the C:\Users\Public\Pictures\Sample Pictures directory exists and that it contains files.

Example

    using System;
    using System.Linq;
    using System.Threading.Tasks;

    class Program
    {
        static void Main()
        {
            // Return a value type with a lambda expression
            Task<int> task1 = Task<int>.Factory.StartNew(() => 1);
            int i = task1.Result;

            // Return a named reference type with a multi-line statement lambda.
            Task<Test> task2 = Task<Test>.Factory.StartNew(() =>
            {
                string s = ".NET";
                double d = 4.0;
                return new Test { Name = s, Number = d };
            });
            Test test = task2.Result;

            // Return an array produced by a PLINQ query
            Task<string[]> task3 = Task<string[]>.Factory.StartNew(() =>
            {
                string path = @"C:\Users\Public\Pictures\Sample Pictures\";
                string[] files = System.IO.Directory.GetFiles(path);

                string[] result = (from file in files.AsParallel()
                              let info = new System.IO.FileInfo(file)
                              where info.Extension == ".jpg"
                              select file).ToArray();

                return result;
            });

