                                                    End If
                                                End Function)
            Try
                lastStep.Wait()
            Catch ae As AggregateException
                For Each ex As Exception In ae.InnerExceptions
                    Console.WriteLine(ex.Message & ex.StackTrace & ex.GetBaseException.ToString())
                Next
            End Try

            Console.WriteLine("Press any key")
            Console.ReadKey()
