How to: Write a simple Parallel.ForEach loop

This article shows how to use a System.Threading.Tasks.Parallel.ForEach*?displayProperty=nameWithType loop to enable data parallelism over any System.Collections.IEnumerable?displayProperty=nameWithType or [System.Collections.Generic.IEnumerable1?displayProperty=nameWithType](xref:System.Collections.Generic.IEnumerable1?displayProperty=nameWithType) data source.

Note

This documentation uses lambda expressions to define delegates in PLINQ. If you aren't familiar with lambda expressions in C# or Visual Basic, see Lambda expressions in PLINQ and TPL.

Example

This example demonstrates System.Threading.Tasks.Parallel.ForEach*?displayProperty=nameWithType for CPU-intensive operations. When you run the example, it randomly generates 2 million numbers and tries to filter to prime numbers. The first case iterates over the collection via a for loop. The second case iterates over the collection via System.Threading.Tasks.Parallel.ForEach*?displayProperty=nameWithType. The resulting time taken by each iteration is displayed when the application is finished.

    using System;
    using System.Collections.Concurrent;
    using System.Collections.Generic;
    using System.Diagnostics;
    using System.Linq;
    using System.Threading.Tasks;

    namespace ParallelExample
    {
        class Program
        {
            static void Main()
            {
                // 2 million
                var limit = 2_000_000;
                var numbers = Enumerable.Range(0, limit).ToList();

                var watch = Stopwatch.StartNew();
                var primeNumbersFromForeach = GetPrimeList(numbers);
                watch.Stop();

                var watchForParallel = Stopwatch.StartNew();
                var primeNumbersFromParallelForeach = GetPrimeListWithParallel(numbers);
                watchForParallel.Stop();

                Console.WriteLine($"Classical foreach loop | Total prime numbers : {primeNumbersFromForeach.Count} | Time Taken : {watch.ElapsedMilliseconds} ms.");
                Console.WriteLine($"Parallel.ForEach loop  | Total prime numbers : {primeNumbersFromParallelForeach.Count} | Time Taken : {watchForParallel.ElapsedMilliseconds} ms.");

                Console.WriteLine("Press 'Enter' to exit.");
                Console.ReadLine();
            }

            /// <summary>
            /// GetPrimeList returns Prime numbers by using sequential ForEach
            /// </summary>
            /// <param name="inputs"></param>
            /// <returns></returns>
            private static IList<int> GetPrimeList(IList<int> numbers) => numbers.Where(IsPrime).ToList();

            /// <summary>
            /// GetPrimeListWithParallel returns Prime numbers by using Parallel.ForEach
            /// </summary>
            /// <param name="numbers"></param>
            /// <returns></returns>
            private static IList<int> GetPrimeListWithParallel(IList<int> numbers)
            {
                var primeNumbers = new ConcurrentBag<int>();

                Parallel.ForEach(numbers, number =>
                {
                    if (IsPrime(number))
                    {
                        primeNumbers.Add(number);
                    }
                });

                return primeNumbers.ToList();
            }

            /// <summary>
            /// IsPrime returns true if number is Prime, else false.(https://en.wikipedia.org/wiki/Prime_number)
            /// </summary>
            /// <param name="number"></param>
            /// <returns></returns>
            private static bool IsPrime(int number)
            {
                if (number < 2)
                {
                    return false;
                }

                for (var divisor = 2; divisor <= Math.Sqrt(number); divisor++)
                {
                    if (number % divisor == 0)
                    {
                        return false;
                    }
                }
                return true;
            }
        }
    }

    Imports System.Collections.Concurrent

