                ' it will be wrapped in AggregateException and propagated to the main thread.
                Console.WriteLine("Parallel.ForEach has thrown an exception. THIS WAS NOT EXPECTED." & vbLf & "{0}", e)
            End Try
        End Sub

    End Module

