            End Function

            Shared Function GetOrderDetailsForOrder(ByVal orderID As Integer) As OrderDetail()
                Dim orderDetails = IO.File.ReadAllLines("..\..\plinqdata.csv").
                    SkipWhile(Function(line) line.StartsWith("ORDER DETAILS") = False).
