                                TakeWhile(Function(line) line.StartsWith("END ORDER DETAILS") = False)

                Dim ordDetailStrings = From line In orderDetails
                                       Let fields = line.Split(","c)
                                       Let ordID = Convert.ToInt32(fields(0))
                                       Where ordID = orderID
                                       Select New OrderDetail With {
                                        .OrderID = ordID,
