You can also use the System.Threading.Tasks.TaskFactory.StartNew*?displayProperty=nameWithType method to create and start a task in one operation. As shown in the following example, you can use this method when:

• Creation and scheduling don't have to be separated and you require additional task creation options or the use of a specific scheduler.

• You need to pass additional state into the task that you can retrieve through its System.Threading.Tasks.Task.AsyncState?displayProperty=nameWithType property.

    using System;
    using System.Threading;
    using System.Threading.Tasks;

    namespace TaskIntro;

    class CustomData
    {
        public long CreationTime;
        public int Name;
        public int ThreadNum;
    }

    public class AsyncState
    {
        public static void Main()
        {
            Task[] taskArray = new Task[10];
            for (int i = 0; i < taskArray.Length; i++)
            {
                taskArray[i] = Task.Factory.StartNew((Object obj) =>
                {
                    CustomData data = obj as CustomData;
                    if (data == null) return;

                    data.ThreadNum = Thread.CurrentThread.ManagedThreadId;
                },
                new CustomData() { Name = i, CreationTime = DateTime.Now.Ticks });
            }
            Task.WaitAll(taskArray);
            foreach (var task in taskArray)
            {
                var data = task.AsyncState as CustomData;
                if (data != null)
                    Console.WriteLine("Task #{0} created at {1}, ran on thread #{2}.",
                                      data.Name, data.CreationTime, data.ThreadNum);
            }
        }
    }
