System.Threading.Tasks.Task and [System.Threading.Tasks.Task1](xref:System.Threading.Tasks.Task1) each expose a static System.Threading.Tasks.Task.Factory property that returns a default instance of System.Threading.Tasks.TaskFactory, so that you can call the method as Task.Factory.StartNew(). Also, in the following example, because the tasks are of type [System.Threading.Tasks.Task1?displayProperty=nameWithType](xref:System.Threading.Tasks.Task1?displayProperty=nameWithType), they each have a public [System.Threading.Tasks.Task1.Result?displayProperty=nameWithType](xref:System.Threading.Tasks.Task1.Result?displayProperty=nameWithType) property that contains the result of the computation. The tasks run asynchronously and might complete in any order. If the [System.Threading.Tasks.Task1.Result](xref:System.Threading.Tasks.Task1.Result) property is accessed before the computation finishes, the property blocks the calling thread until the value is available.

    using System;
    using System.Threading.Tasks;

    public class Result
    {
       public static void Main()
       {
            Task<Double>[] taskArray = { Task<Double>.Factory.StartNew(() => DoComputation(1.0)),
                                         Task<Double>.Factory.StartNew(() => DoComputation(100.0)),
                                         Task<Double>.Factory.StartNew(() => DoComputation(1000.0)) };

            var results = new Double[taskArray.Length];
            Double sum = 0;

            for (int i = 0; i < taskArray.Length; i++) {
                results[i] = taskArray[i].Result;
                Console.Write("{0:N1} {1}", results[i],
                                  i == taskArray.Length - 1 ? "= " : "+ ");
                sum += results[i];
            }
            Console.WriteLine($"{sum:N1}");
       }

       private static Double DoComputation(Double start)
       {
          Double sum = 0;
          for (var value = start; value <= start + 10; value += .1)
             sum += value;

          return sum;
       }
    }
    // The example displays the following output:
    //        606.0 + 10,605.0 + 100,495.0 = 111,706.0

