Defining Employee Database Operations

Add to the Program class the InsertEmployees, GetEmployeeCount, and GetEmployeeID methods.

    // Adds new employee records to the database.
    static void InsertEmployees(Employee[] employees, string connectionString)
    {
       using (SqlConnection connection =
          new SqlConnection(connectionString))
       {
          try
          {
             // Create the SQL command.
             SqlCommand command = new SqlCommand(
                $"INSERT INTO [{s_employeeTable}] ([Last Name], [First Name])" +
                "VALUES (@lastName, @firstName)",
                connection);

             connection.Open();
             for (int i = 0; i < employees.Length; i++)
             {
                // Set parameters.
                command.Parameters.Clear();
                command.Parameters.AddWithValue("@lastName", employees[i].LastName);
                command.Parameters.AddWithValue("@firstName", employees[i].FirstName);

                // Execute the command.
                command.ExecuteNonQuery();
             }
          }
          finally
          {
             connection.Close();
          }
       }
    }

    // Retrieves the number of entries in the sample employee table.
    static int GetEmployeeCount(string connectionString)
    {
       int result = 0;
       using (SqlConnection sqlConnection =
          new SqlConnection(connectionString))
       {
          SqlCommand sqlCommand = new SqlCommand(
             $"SELECT COUNT(*) FROM [{s_employeeTable}]", sqlConnection);

          sqlConnection.Open();
          try
          {
             result = (int)sqlCommand.ExecuteScalar();
          }
          finally
          {
             sqlConnection.Close();
          }
       }
       return result;
    }

    // Retrieves the ID of the first employee that has the provided name.
    static int GetEmployeeID(string lastName, string firstName,
       string connectionString)
    {
       using (SqlConnection connection =
          new SqlConnection(connectionString))
       {
          SqlCommand command = new SqlCommand(
             $"SELECT TOP (1) [Employee ID] FROM [{s_employeeTable}] " +
             "WHERE [Last Name] = @lastName AND [First Name] = @firstName ORDER BY [Employee ID]",
             connection);

          command.Parameters.Add("@lastName", System.Data.SqlDbType.NVarChar).Value = lastName;
          command.Parameters.Add("@firstName", System.Data.SqlDbType.NVarChar).Value = firstName;

          connection.Open();
          try
          {
             object result = command.ExecuteScalar();
             if (result == null)
                throw new KeyNotFoundException("No matching employee.");
             return (int)result;
          }
          finally
          {
             connection.Close();
          }
       }
    }

    ' Adds new employee records to the database.
    Private Shared Sub InsertEmployees(ByVal employees() As Employee, ByVal connectionString As String)
        Using connection As New SqlConnection(connectionString)
            Try
                ' Create the SQL command.
                Dim command As New SqlCommand($"INSERT INTO [{s_employeeTable}] ([Last Name], [First Name]) VALUES (@lastName, @firstName)", connection)

                connection.Open()
                For i As Integer = 0 To employees.Length - 1
                    ' Set parameters.
                    command.Parameters.Clear()
                    command.Parameters.Add("@lastName", SqlDbType.NVarChar).Value = employees(i).LastName
                    command.Parameters.Add("@firstName", SqlDbType.NVarChar).Value = employees(i).FirstName

                    ' Execute the command.
                    command.ExecuteNonQuery()
                Next i
            Finally
                connection.Close()
            End Try
        End Using
    End Sub

    ' Retrieves the number of entries in the sample employee table.
    Private Shared Function GetEmployeeCount(ByVal connectionString As String) As Integer
        Dim result As Integer = 0
        Using sqlConnection As New SqlConnection(connectionString)
            Dim sqlCommand As New SqlCommand($"SELECT COUNT(*) FROM [{s_employeeTable}]", sqlConnection)

            sqlConnection.Open()
            Try
                result = CInt(Fix(sqlCommand.ExecuteScalar()))
            Finally
                sqlConnection.Close()
            End Try
        End Using
        Return result
    End Function

    ' Retrieves the ID of the first employee that has the provided name.
    Private Shared Function GetEmployeeID(ByVal lastName As String, ByVal firstName As String, ByVal connectionString As String) As Integer
        Using connection As New SqlConnection(connectionString)
            Dim query As String = $"SELECT TOP (1) [Employee ID] FROM [{s_employeeTable}] WHERE [Last Name] = @lastName AND [First Name] = @firstName ORDER BY [Employee ID]"
            Dim command As New SqlCommand(query, connection)
            command.Parameters.Add("@lastName", SqlDbType.NVarChar, 50).Value = lastName
            command.Parameters.Add("@firstName", SqlDbType.NVarChar, 50).Value = firstName

            connection.Open()
            Try
                Dim result = command.ExecuteScalar()
                If result Is Nothing Then
                    Throw New KeyNotFoundException("No matching employee.")
                End If
                Return CInt(result)
            Finally
                connection.Close()
            End Try
        End Using
    End Function

The InsertEmployees method adds new employee records to the temporary table. The GetEmployeeCount method retrieves the number of entries in that table. The GetEmployeeID method retrieves the identifier of the first employee that has the provided name, or throws System.Collections.Generic.KeyNotFoundException if no employee matches. Each method takes the connection string for your development database.

