Create an asymmetric key

This task creates an asymmetric key that encrypts and decrypts the System.Security.Cryptography.Aes key. This key was used to encrypt the content and it displays the key container name on the label control.

Add the following code as the Click event handler for the Create Keys button (buttonCreateAsmKeys_Click).

    private void buttonCreateAsmKeys_Click(object sender, EventArgs e)
    {
        // Stores a key pair in the key container.
        _cspp.KeyContainerName = KeyName;
        _rsa = new RSACryptoServiceProvider(_cspp)
        {
            PersistKeyInCsp = true
        };

        label1.Text = _rsa.PublicOnly
            ? $"Key: {_cspp.KeyContainerName} - Public Only"
            : $"Key: {_cspp.KeyContainerName} - Full Key Pair";
    }

    Private Sub buttonCreateAsmKeys_Click(ByVal sender As Object, ByVal e As EventArgs) Handles buttonCreateAsmKeys.Click
        ' Stores a key pair in the key container.
        _cspp.KeyContainerName = KeyName
        _rsa = New RSACryptoServiceProvider(_cspp) With {
            .PersistKeyInCsp = True
        }

        If _rsa.PublicOnly Then
            Label1.Text = $"Key: {_cspp.KeyContainerName} - Public Only"
        Else
            Label1.Text = $"Key: {_cspp.KeyContainerName} - Full Key Pair"
        End If

    End Sub

Encrypt a file

This task involves two methods: the event handler method for the Encrypt File button (buttonEncryptFile_Click) and the EncryptFile method. The first method displays a dialog box for selecting a file and passes the file name to the second method, which performs the encryption.

The encrypted content, key, and IV are all saved to one System.IO.FileStream, which is referred to as the encryption package.

The EncryptFile method does the following:

• Creates a System.Security.Cryptography.Aes symmetric algorithm to encrypt the content.

• Creates an System.Security.Cryptography.RSACryptoServiceProvider object to encrypt the System.Security.Cryptography.Aes key.

• Uses a System.Security.Cryptography.CryptoStream object to read and encrypt the System.IO.FileStream of the source file, in blocks of bytes, into a destination System.IO.FileStream object for the encrypted file.

• Determines the lengths of the encrypted key and IV, and creates byte arrays of their length values.

• Writes the Key, IV, and their length values to the encrypted package.

The encryption package uses the following format:

• Key length, bytes 0 - 3

• IV length, bytes 4 - 7

• Encrypted key

• IV

• Cipher text

You can use the lengths of the key and IV to determine the starting points and lengths of all parts of the encryption package, which can then be used to decrypt the file.

Add the following code as the Click event handler for the Encrypt File button (buttonEncryptFile_Click).

    private void buttonEncryptFile_Click(object sender, EventArgs e)
    {
        if (_rsa is null)
        {
            MessageBox.Show("Key not set.");
        }
        else
        {
            // Display a dialog box to select a file to encrypt.
            _encryptOpenFileDialog.InitialDirectory = SrcFolder;
            if (_encryptOpenFileDialog.ShowDialog() == DialogResult.OK)
            {
                string fName = _encryptOpenFileDialog.FileName;
                if (fName != null)
                {
                    // Pass the file name without the path.
                    EncryptFile(new FileInfo(fName));
                }
            }
        }
    }

    Private Sub buttonEncryptFile_Click(ByVal sender As Object, ByVal e As EventArgs) Handles buttonEncryptFile.Click
        If _rsa Is Nothing Then
            MsgBox("Key not set.")
        Else
            ' Display a dialog box to select a file to encrypt.
            _encryptOpenFileDialog.InitialDirectory = SrcFolder
            If _encryptOpenFileDialog.ShowDialog = Windows.Forms.DialogResult.OK Then
                Try
                    Dim fName As String = _encryptOpenFileDialog.FileName
                    If (Not (fName) Is Nothing) Then
                        Dim fInfo As New FileInfo(fName)
                        ' Use just the file name without path.
                        Dim name As String = fInfo.FullName
                        EncryptFile(name)
                    End If
                Catch ex As Exception
                    MsgBox(ex.Message)
                End Try
            End If
        End If
    End Sub

Add the following EncryptFile method to the form.

    private void EncryptFile(FileInfo file)
    {
        // Create instance of Aes for
        // symmetric encryption of the data.
        Aes aes = Aes.Create();
        ICryptoTransform transform = aes.CreateEncryptor();

        // Use RSACryptoServiceProvider to
        // encrypt the AES key.
        // rsa is previously instantiated:
        //    rsa = new RSACryptoServiceProvider(cspp);
        byte[] keyEncrypted = _rsa.Encrypt(aes.Key, false);

        // Create byte arrays to contain
        // the length values of the key and IV.
        int lKey = keyEncrypted.Length;
        byte[] LenK = BitConverter.GetBytes(lKey);
        int lIV = aes.IV.Length;
        byte[] LenIV = BitConverter.GetBytes(lIV);

        // Write the following to the FileStream
        // for the encrypted file (outFs):
        // - length of the key
        // - length of the IV
        // - encrypted key
        // - the IV
        // - the encrypted cipher content

        // Change the file's extension to ".enc"
        string outFile =
            Path.Combine(EncrFolder, Path.ChangeExtension(file.Name, ".enc"));

        using (var outFs = new FileStream(outFile, FileMode.Create))
        {
            outFs.Write(LenK, 0, 4);
            outFs.Write(LenIV, 0, 4);
            outFs.Write(keyEncrypted, 0, lKey);
            outFs.Write(aes.IV, 0, lIV);

            // Now write the cipher text using
            // a CryptoStream for encrypting.
            using (var outStreamEncrypted =
                new CryptoStream(outFs, transform, CryptoStreamMode.Write))
            {
                // By encrypting a chunk at
                // a time, you can save memory
                // and accommodate large files.
                int count = 0;
                int offset = 0;

                // blockSizeBytes can be any arbitrary size.
                int blockSizeBytes = aes.BlockSize / 8;
                byte[] data = new byte[blockSizeBytes];
                int bytesRead = 0;

                using (var inFs = new FileStream(file.FullName, FileMode.Open))
                {
                    do
                    {
                        count = inFs.Read(data, 0, blockSizeBytes);
                        offset += count;
                        outStreamEncrypted.Write(data, 0, count);
                        bytesRead += blockSizeBytes;
                    } while (count > 0);
                }
                outStreamEncrypted.FlushFinalBlock();
            }
        }
    }

    Private Sub EncryptFile(ByVal inFile As String)
        ' Create instance of Aes for
        ' symmetric encryption of the data.
        Dim aes As Aes = Aes.Create()
        Dim transform As ICryptoTransform = aes.CreateEncryptor

        ' Use RSACryptoServiceProvider to
        ' encrypt the AES key.
        Dim keyEncrypted() As Byte = _rsa.Encrypt(aes.Key, False)

        ' Create byte arrays to contain
        ' the length values of the key and IV.
        Dim LenK() As Byte = New Byte((4) - 1) {}
        Dim LenIV() As Byte = New Byte((4) - 1) {}
        Dim lKey As Integer = keyEncrypted.Length
        LenK = BitConverter.GetBytes(lKey)
        Dim lIV As Integer = aes.IV.Length
        LenIV = BitConverter.GetBytes(lIV)

        ' Write the following to the FileStream
        ' for the encrypted file (outFs):
        ' - length of the key
        ' - length of the IV
        ' - encrypted key
        ' - the IV
        ' - the encrypted cipher content
        ' Change the file's extension to ".enc"
        Dim startFileName As Integer = inFile.LastIndexOf("\") + 1
        Dim outFile As String = (EncrFolder _
                    + (inFile.Substring(startFileName, inFile.LastIndexOf(".") - startFileName) + ".enc"))

        Using outFs As New FileStream(outFile, FileMode.Create)
            outFs.Write(LenK, 0, 4)
            outFs.Write(LenIV, 0, 4)
            outFs.Write(keyEncrypted, 0, lKey)
            outFs.Write(aes.IV, 0, lIV)

            ' Now write the cipher text using
            ' a CryptoStream for encrypting.
            Using outStreamEncrypted As New CryptoStream(outFs, transform, CryptoStreamMode.Write)
                ' By encrypting a chunk at
                ' a time, you can save memory
                ' and accommodate large files.
                Dim count As Integer = 0
                Dim offset As Integer = 0

                ' blockSizeBytes can be any arbitrary size.
                Dim blockSizeBytes As Integer = (aes.BlockSize / 8)
                Dim data() As Byte = New Byte((blockSizeBytes) - 1) {}
                Dim bytesRead As Integer = 0
                Using inFs As New FileStream(inFile, FileMode.Open)
                    Do
                        count = inFs.Read(data, 0, blockSizeBytes)
                        offset = (offset + count)
                        outStreamEncrypted.Write(data, 0, count)
                        bytesRead = (bytesRead + blockSizeBytes)
                    Loop Until (count = 0)

                    outStreamEncrypted.FlushFinalBlock()
                    inFs.Close()
                End Using
                outStreamEncrypted.Close()
            End Using
            outFs.Close()
        End Using
    End Sub

Decrypt a file

This task involves two methods, the event handler method for the Decrypt File button (buttonDecryptFile_Click), and the DecryptFile method. The first method displays a dialog box for selecting a file and passes its file name to the second method, which performs the decryption.

The Decrypt method does the following:

• Creates an System.Security.Cryptography.Aes symmetric algorithm to decrypt the content.

• Reads the first eight bytes of the System.IO.FileStream of the encrypted package into byte arrays to obtain the lengths of the encrypted key and the IV.

• Extracts the key and IV from the encryption package into byte arrays.

• Creates an System.Security.Cryptography.RSACryptoServiceProvider object to decrypt the System.Security.Cryptography.Aes key.

• Uses a System.Security.Cryptography.CryptoStream object to read and decrypt the cipher text section of the System.IO.FileStream encryption package, in blocks of bytes, into the System.IO.FileStream object for the decrypted file. When this is finished, the decryption is completed.

Add the following code as the Click event handler for the Decrypt File button.

    private void buttonDecryptFile_Click(object sender, EventArgs e)
    {
        if (_rsa is null)
        {
            MessageBox.Show("Key not set.");
        }
        else
        {
            // Display a dialog box to select the encrypted file.
            _decryptOpenFileDialog.InitialDirectory = EncrFolder;
            if (_decryptOpenFileDialog.ShowDialog() == DialogResult.OK)
            {
                string fName = _decryptOpenFileDialog.FileName;
                if (fName != null)
                {
                    DecryptFile(new FileInfo(fName));
                }
            }
        }
    }

    Private Sub buttonDecryptFile_Click(ByVal sender As Object, ByVal e As EventArgs) Handles buttonDecryptFile.Click
        If _rsa Is Nothing Then
            MsgBox("Key not set.")
        Else
            ' Display a dialog box to select the encrypted file.
            _decryptOpenFileDialog.InitialDirectory = EncrFolder
            If (_decryptOpenFileDialog.ShowDialog = Windows.Forms.DialogResult.OK) Then
                Try
                    Dim fName As String = _decryptOpenFileDialog.FileName
                    If ((fName) IsNot Nothing) Then
                        Dim fi As New FileInfo(fName)
                        Dim name As String = fi.Name
                        DecryptFile(name)
                    End If
                Catch ex As Exception
                    MessageBox.Show(ex.Message)
                End Try
            End If
        End If
    End Sub

Add the following DecryptFile method to the form.

    private void DecryptFile(FileInfo file)
    {
        // Create instance of Aes for
        // symmetric decryption of the data.
        Aes aes = Aes.Create();

        // Create byte arrays to get the length of
        // the encrypted key and IV.
        // These values were stored as 4 bytes each
        // at the beginning of the encrypted package.
        byte[] LenK = new byte[4];
        byte[] LenIV = new byte[4];

        // Construct the file name for the decrypted file.
        string outFile =
            Path.ChangeExtension(file.FullName.Replace("Encrypt", "Decrypt"), ".txt");

        // Use FileStream objects to read the encrypted
        // file (inFs) and save the decrypted file (outFs).
        using (var inFs = new FileStream(file.FullName, FileMode.Open))
        {
            inFs.Seek(0, SeekOrigin.Begin);
            inFs.Read(LenK, 0, 3);
            inFs.Seek(4, SeekOrigin.Begin);
            inFs.Read(LenIV, 0, 3);

            // Convert the lengths to integer values.
            int lenK = BitConverter.ToInt32(LenK, 0);
            int lenIV = BitConverter.ToInt32(LenIV, 0);

            // Determine the start position of
            // the cipher text (startC)
            // and its length(lenC).
            int startC = lenK + lenIV + 8;
            int lenC = (int)inFs.Length - startC;

            // Create the byte arrays for
            // the encrypted Aes key,
            // the IV, and the cipher text.
            byte[] KeyEncrypted = new byte[lenK];
            byte[] IV = new byte[lenIV];

            // Extract the key and IV
            // starting from index 8
            // after the length values.
            inFs.Seek(8, SeekOrigin.Begin);
            inFs.Read(KeyEncrypted, 0, lenK);
            inFs.Seek(8 + lenK, SeekOrigin.Begin);
            inFs.Read(IV, 0, lenIV);

            Directory.CreateDirectory(DecrFolder);
            //<Snippet10>
            // Use RSACryptoServiceProvider
            // to decrypt the AES key.
            byte[] KeyDecrypted = _rsa.Decrypt(KeyEncrypted, false);

            // Decrypt the key.
            ICryptoTransform transform = aes.CreateDecryptor(KeyDecrypted, IV);
            //</Snippet10>

            // Decrypt the cipher text from
            // from the FileSteam of the encrypted
            // file (inFs) into the FileStream
            // for the decrypted file (outFs).
            using (var outFs = new FileStream(outFile, FileMode.Create))
            {
                int count = 0;
                int offset = 0;

                // blockSizeBytes can be any arbitrary size.
                int blockSizeBytes = aes.BlockSize / 8;
                byte[] data = new byte[blockSizeBytes];

                // By decrypting a chunk a time,
                // you can save memory and
                // accommodate large files.

                // Start at the beginning
                // of the cipher text.
                inFs.Seek(startC, SeekOrigin.Begin);
                using (var outStreamDecrypted =
                    new CryptoStream(outFs, transform, CryptoStreamMode.Write))
                {
                    do
                    {
                        count = inFs.Read(data, 0, blockSizeBytes);
                        offset += count;
                        outStreamDecrypted.Write(data, 0, count);
                    } while (count > 0);

                    outStreamDecrypted.FlushFinalBlock();
                }
            }
        }
    }

    Private Sub DecryptFile(ByVal inFile As String)
        ' Create instance of Aes for
        ' symmetric decryption of the data.
        Dim aes As Aes = Aes.Create()

        ' Create byte arrays to get the length of
        ' the encrypted key and IV.
        ' These values were stored as 4 bytes each
        ' at the beginning of the encrypted package.
        Dim LenK() As Byte = New Byte(4 - 1) {}
        Dim LenIV() As Byte = New Byte(4 - 1) {}

        ' Construct the file name for the decrypted file.
        Dim outFile As String = (DecrFolder _
                    + (inFile.Substring(0, inFile.LastIndexOf(".")) + ".txt"))

        ' Use FileStream objects to read the encrypted
        ' file (inFs) and save the decrypted file (outFs).
        Using inFs As New FileStream((EncrFolder + inFile), FileMode.Open)

            inFs.Seek(0, SeekOrigin.Begin)
            inFs.Read(LenK, 0, 3)
            inFs.Seek(4, SeekOrigin.Begin)
            inFs.Read(LenIV, 0, 3)

            Dim lengthK As Integer = BitConverter.ToInt32(LenK, 0)
            Dim lengthIV As Integer = BitConverter.ToInt32(LenIV, 0)
            Dim startC As Integer = (lengthK + lengthIV + 8)
            Dim lenC As Integer = (CType(inFs.Length, Integer) - startC)
            Dim KeyEncrypted() As Byte = New Byte(lengthK - 1) {}
            Dim IV() As Byte = New Byte(lengthIV - 1) {}

            ' Extract the key and IV
            ' starting from index 8
            ' after the length values.
            inFs.Seek(8, SeekOrigin.Begin)
            inFs.Read(KeyEncrypted, 0, lengthK)
            inFs.Seek(8 + lengthK, SeekOrigin.Begin)
            inFs.Read(IV, 0, lengthIV)
            Directory.CreateDirectory(DecrFolder)
            '<Snippet10>
            ' User RSACryptoServiceProvider
            ' to decrypt the AES key
            Dim KeyDecrypted() As Byte = _rsa.Decrypt(KeyEncrypted, False)

            ' Decrypt the key.
            Dim transform As ICryptoTransform = aes.CreateDecryptor(KeyDecrypted, IV)
            '</Snippet10>
            ' Decrypt the cipher text from
            ' from the FileSteam of the encrypted
            ' file (inFs) into the FileStream
            ' for the decrypted file (outFs).
            Using outFs As New FileStream(outFile, FileMode.Create)
                Dim count As Integer = 0
                Dim offset As Integer = 0

                ' blockSizeBytes can be any arbitrary size.
                Dim blockSizeBytes As Integer = (aes.BlockSize / 8)
                Dim data() As Byte = New Byte(blockSizeBytes - 1) {}
                ' By decrypting a chunk a time,
                ' you can save memory and
                ' accommodate large files.
                ' Start at the beginning
                ' of the cipher text.
                inFs.Seek(startC, SeekOrigin.Begin)
                Using outStreamDecrypted As New CryptoStream(outFs, transform, CryptoStreamMode.Write)
                    Do
                        count = inFs.Read(data, 0, blockSizeBytes)
                        offset += count
                        outStreamDecrypted.Write(data, 0, count)
                    Loop Until (count = 0)

                    outStreamDecrypted.FlushFinalBlock()
                End Using
            End Using
        End Using
    End Sub

