Serialization extension methods on HttpClient

Serializing and deserializing JSON payloads from the network are common operations. Extension methods on HttpClient and HttpContent let you do these operations in a single line of code. These extension methods use web defaults for JsonSerializerOptions.

The following example illustrates use of System.Net.Http.Json.HttpClientJsonExtensions.GetFromJsonAsync*?displayProperty=nameWithType and System.Net.Http.Json.HttpClientJsonExtensions.PostAsJsonAsync*?displayProperty=nameWithType:

    using System.Net.Http.Json;

    namespace HttpClientExtensionMethods
    {
        public class User
        {
            public int Id { get; set; }
            public string? Name { get; set; }
            public string? Username { get; set; }
            public string? Email { get; set; }
        }

        public class Program
        {
            public static async Task Run()
            {
                using HttpClient client = new()
                {
                    BaseAddress = new Uri("https://jsonplaceholder.typicode.com")
                };

                // Get the user information.
                User? user = await client.GetFromJsonAsync<User>("users/1");
                Console.WriteLine($"Id: {user?.Id}");
                Console.WriteLine($"Name: {user?.Name}");
                Console.WriteLine($"Username: {user?.Username}");
                Console.WriteLine($"Email: {user?.Email}");

                // Post a new user.
                HttpResponseMessage response = await client.PostAsJsonAsync("users", user);
                Console.WriteLine(
                    $"{(response.IsSuccessStatusCode ? "Success" : "Error")} - {response.StatusCode}");
            }
        }
    }

    // Produces output like the following example but with different names:
    //
    //Id: 1
    //Name: Tyler King
    //Username: Tyler
    //Email: Tyler@contoso.com
    //Success - Created

