            Private Class Node
                Public [Next] As Node
                Public Value As T
            End Class

            Public Sub Push(ByVal item As T)
                Dim spin As New SpinWait()
                Dim head As Node, node As New Node With {.Value = item}

                While True
                    Thread.MemoryBarrier()
                    head = m_head
                    node.Next = head
                    If Interlocked.CompareExchange(m_head, node, head) Is head Then Exit While
                    spin.SpinOnce()
                End While
