                Dim spin As New SpinWait()

                Dim head As Node
                While True
                    Thread.MemoryBarrier()
                    head = m_head
                    If head Is Nothing Then Return False
                    If Interlocked.CompareExchange(m_head, head.Next, head) Is head Then
                        result = head.Value
                        Return True
                    End If
                    spin.SpinOnce()
                End While
            End Function
